// Saturated add or sub
function automatic logic [4:0] AddSub(logic [4:0] a, logic [4:0] b, logic add, logic half);
    logic [5:0] temp;
    if (add) begin
        temp = {1'b0, a} + {1'b0, b};
        if (temp[5] && !half)
            temp = 6'b111111;
    end else begin
        temp = {1'b0, a} - {1'b0, b};
        if (temp[5])
            temp = 6'b0;
    end
    if (half)
        return temp[5:1];
    else
        return temp[4:0];
endfunction

function automatic logic [14:0] GetDCM(logic [10:0] a);
    return {a[7:6], a[10], 2'b00, a[5:3], a[9], 1'b0, a[2:0], a[8], 1'b0};
endfunction

function automatic logic [4:0] Bright(logic [3:0] mb, logic [4:0] b);
    logic [8:0] temp;
    temp = b * mb + {4'b0, b};
    if (mb == 4'b0)
        return 5'b0;
    else
        return temp[8:4];
endfunction

function automatic logic signed [15:0] Mode7Clip(logic signed [13:0] a);
    return {{6{a[13]}}, a[9:0]};
endfunction;



