// clamp a 17-bit signed integer to 16-bit signed (max 0x7fff and min 0x8000)
function automatic logic signed [15:0] CLAMP16(logic signed [16:0] a);
    return a[16:15] == 2'b01 ? 16'h7fff :
           a[16:15] == 2'b10 ? 16'h8000 :
           16'(a);
endfunction


