typedef logic [11:0] GCntMask_t [0:31];
localparam GCntMask_t GCNT_MASK = '{
    12'hFFF, 12'h7FF, 12'h7FF,
    12'h7FF, 12'h3FF, 12'h3FF,
    12'h3FF, 12'h1FF, 12'h1FF,
    12'h1FF, 12'h0FF, 12'h0FF,
    12'h0FF, 12'h07F, 12'h07F,
    12'h07F, 12'h03F, 12'h03F,
    12'h03F, 12'h01F, 12'h01F,
    12'h01F, 12'h00F, 12'h00F,
    12'h00F, 12'h007, 12'h007,
    12'h007, 12'h003, 12'h003,
             12'h001,
             12'h000 };

function automatic logic GCOUNT_TRIGGER(logic [4:0] r);
    case (r)
    1, 4, 7, 10, 13, 16, 19, 22, 25, 28, 30:
        return (GCNT_BY1 & GCNT_MASK[r]) == 12'b0;
    2, 5, 8, 11, 14, 17, 20, 23, 26, 29:
        return (GCNT_BY3 & GCNT_MASK[r]) == 12'b0;
    3, 6, 9, 12, 15, 18, 21, 24, 27:
        return (GCNT_BY5 & GCNT_MASK[r]) == 12'b0;
    31:
        return 1'b1;
    default:
        return 1'b0;
    endcase
endfunction

VoiceStep_r VS;
wire [3:0] RS;
BRRDecodeStep_r BDS;
IntStep_r INS;

//debug
reg [15:0] DBG_ADDR;
reg DBG_DAT_WRr;
reg [7:0] DBG_VMUTE = 8'b0;

wire CE;
wire CEGEN_RST_N = RST_N & ENABLE;

CEGen cegen (
  .CLK(CLK), .RST_N(CEGEN_RST_N),
  .IN_CLK(2147727),
  .OUT_CLK(ACLK_FREQ),
  .CE(CE)
);

assign SMP_EN = SMP_EN_INT;
assign SMP_CE = CE;

always @(posedge CLK) begin
    if (~RST_N) begin
        STEP_CNT <= 5'b0;
        SUBSTEP_CNT <= 2'b0;
    end else if (ENABLE && CE) begin
        SUBSTEP_CNT <= SUBSTEP_CNT + 1;
        if (SUBSTEP_CNT == 3)
            STEP_CNT <= STEP_CNT + 1;
    end
end

assign SMP_EN_INT = SUBSTEP == 3 ? ENABLE : 1'b0;

assign STEP = STEP_CNT;
assign SUBSTEP = SUBSTEP_CNT;

assign REGS_ADDR_WR = /* ENABLE == 1'b0 ? DBG_REG[6:0] :*/ REGN_WR;
assign REGS_ADDR_RD = /* ENABLE == 1'b0 ? DBG_REG[6:0] :*/ REGN_RD;
assign REGS_DI = /*ENABLE == 1'b0 ? DBG_DAT_IN :*/ SUBSTEP == 3 ? SMP_DO :
                REGN_WR[3:0] == 4'h8 ? ENVX_OUT :
                REGN_WR[3:0] == 4'h9 ? OUTX_OUT :
                SMP_DO;
assign REGS_WE = /*ENABLE == 1'b0 && DBG_REG[7] == 1'b0 ? DBG_DAT_WR : */
                ~SMP_WE_N && !RI[7] && SMP_A == 16'h00F3 && SUBSTEP == 3 && CE ? 1'b1 :
                REGN_WR[3:1] == 3'b100 && SUBSTEP == 0 && CE ? 1'b1 :
                1'b0;

// Dual-port BRAM for registers (128 bytes)
reg [7:0] REGRAM[0:127]     /* synthesis syn_ramstyle = "block_ram" */;
always @(posedge CLK) begin
    if (REGS_WE) begin
        REGRAM[REGS_ADDR_WR] <= REGS_DI;
        // $display("DSP register [%x] <= %x", REGS_ADDR_WR, REGS_DI);
    end
end
always @(posedge CLK) begin
    REGS_DO <= REGRAM[REGS_ADDR_RD];
end

always @(posedge CLK) begin
    if (~RST_N) begin
        RI <= 8'b0;
    end else if (ENABLE && CE) begin
        if (SMP_EN_INT && ~SMP_WE_N && SMP_A == 16'h00F2)
            RI <= SMP_DO;
    end
end

always @* begin
    if (SMP_A == 16'h00F2)
        SMP_DI = RI;
    else if (SMP_A == 16'h00F3) begin
        if (RI[6:0] == 7'b1111100)    //ENDX
            SMP_DI = ENDX;
        else
            SMP_DI = REGS_DO;
    end else
        SMP_DI = RAM_DI;
end

always @* begin : reg_read
    reg [7:0] REG;

    REG = RA_TBL[STEP][SUBSTEP];
    if (SUBSTEP == 3)
        REGN_RD = RI[6:0];
    else if (REG[3:0] == 4'h6)
        REGN_RD = {REG[6:1], ~TADSR1[7]};
    else
        REGN_RD = REG[6:0];

    if (SUBSTEP == 3)
        REGN_WR = RI[6:0];
    else
        REGN_WR = RA_TBL[STEP][SUBSTEP][6:0];
end

assign VS = VS_TBL[STEP][SUBSTEP];
assign RS = RS_TBL[STEP][SUBSTEP];
assign BRR_VOICE = BRR_VOICE_TBL[STEP];
assign BDS = BDS_TBL[STEP][SUBSTEP];
assign INS = IS_TBL[STEP][SUBSTEP];

reg [7:0] SMP_DO_buf;
reg [15:0] SMP_A_buf;
reg SMP_WE_N_buf;
always @(posedge CLK) begin
    SMP_DO_buf <= SMP_DO;
    SMP_A_buf <= SMP_A;
    SMP_WE_N_buf <= SMP_WE_N;
end

always @* begin : ram_addrgen
    reg [1:0] ADDR_INC;
    reg LR;

    RAM_DO = 8'h00;
    ADDR_INC = 2'b0;        // remove latch
    LR = 0;                 // remove latch
    case (RS)
    RS_SRCNL : begin      // 4: read directory entry low 8bit
        if (KON_CNT[BRR_VOICE] == 0)
            ADDR_INC = 2'b10;
        else
            ADDR_INC = 2'b00;

        RAM_A = TDIR_ADDR + 16'(ADDR_INC);
        RAM_WE = 1'b0;
        RAM_OE = 1'b1;
        RAM_CE = 1'b1;
    end

    RS_SRCNH : begin      // 5: read directory entry high 8bit
        if (KON_CNT[BRR_VOICE] == 0)
            ADDR_INC = 2'b10;
        else
            ADDR_INC = 2'b00;

        RAM_A = TDIR_ADDR + 16'(ADDR_INC) + 16'd1;
        RAM_WE = 1'b0;
        RAM_OE = 1'b1;
        RAM_CE = 1'b1;
    end

    RS_BRRH : begin       // 1: read BRR header
        RAM_A = BRR_ADDR[BRR_VOICE];
        RAM_WE = 1'b0;
        RAM_OE = 1'b1;
        RAM_CE = 1'b1;
    end

    RS_BRR1 : begin       // 2: read BRR higher 2 nibble
        RAM_A = BRR_ADDR[BRR_VOICE] + 16'(BRR_OFFS[BRR_VOICE]) + 16'd1;
        RAM_WE = 1'b0;
        RAM_OE = 1'b1;
        RAM_CE = 1'b1;
    end

    RS_BRR2 : begin       // 3: read BRR block 2
        RAM_A = BRR_ADDR[BRR_VOICE] + 16'(BRR_OFFS[BRR_VOICE]) + 16'd2;
        RAM_WE = 1'b0;
        RAM_OE = 1'b1;
        RAM_CE = 1'b1;
    end

    RS_ECHORDL,RS_ECHORDH : begin // 6, 7
        if (STEP == 22)
            ADDR_INC = 2'b00;
        else
            ADDR_INC = 2'b10;

        if (RS == RS_ECHORDL)
            RAM_A = ECHO_ADDR + 16'(ADDR_INC);
        else
            RAM_A = ECHO_ADDR + 16'(ADDR_INC) + 16'd1;

        RAM_WE = 1'b0;
        RAM_OE = 1'b1;
        RAM_CE = 1'b1;
    end

    RS_ECHOWRL,RS_ECHOWRH : begin // 8, 9
        if (STEP == 29) begin
            ADDR_INC = 2'b00;
            LR = 0;
        end else begin
            ADDR_INC = 2'b10;
            LR = 1;
        end

        if (RS == RS_ECHOWRL) begin
            RAM_A = ECHO_ADDR + 16'(ADDR_INC);
            RAM_DO = EOUT[LR][7:0];
        end else begin
            RAM_A = ECHO_ADDR + 16'(ADDR_INC) + 16'd1;
            RAM_DO = EOUT[LR][15:8];
        end

        if (ECHO_WR_EN) begin
            RAM_CE = 1'b1;
            RAM_OE = 1'b0;
            RAM_WE = 1'b1;
        end else begin
            RAM_CE = 1'b0;
            RAM_OE = 1'b0;
            RAM_WE = 1'b0;
        end
    end

    // nand2mario: do memory operation in the first phase, so that read data is
    // available to SMP in second(last) phase earlier (end of first phase), for better timing
    RS_SMP : begin
        RAM_A = SMP_A_buf;
        RAM_WE = ~SMP_WE_N_buf;
        RAM_OE = SMP_WE_N_buf;
        RAM_DO = SMP_DO_buf;            // buffered to satisfy timing checker
        if (SMP_A_buf[15:4]== 12'h00F)
            RAM_CE = 0;
        else
            RAM_CE = 1;
    end

    default : begin
        RAM_A = 16'b0;
        RAM_WE = 1'b0;
        RAM_OE = 1'b0;
        RAM_CE = 1'b0;
    end
    endcase

end

always @(posedge CLK) begin : ram_process
    reg LR;

    if (~RST_N) begin
        BRR_NEXT_ADDR <= 16'b0;
        TBRRHDR <= 8'b0;
        TBRRDAT <= 16'b0;
        ECHO_BUF <= '{2{'{8{15'b0}}}};
        ECHO_DATA_TEMP <= 7'b0;
    end else if (ENABLE && CE) begin
        case (RS)
        RS_SRCNL :
            BRR_NEXT_ADDR[7:0] <= RAM_DI;
        RS_SRCNH :
            BRR_NEXT_ADDR[15:8] <= RAM_DI;
        RS_BRRH :  begin
            TBRRHDR <= RAM_DI;
            // if (started && BRR_VOICE == 3)
            //     $fdisplay(32'h80000002, "BRR header=%x", RAM_DI);
        end
        RS_BRR1 :  begin
            TBRRDAT[15:8] <= RAM_DI;
            // if (started && BRR_VOICE == 3)
            //     $fdisplay(32'h80000002, "BRR datah=%x", RAM_DI);
        end
        RS_BRR2 : begin
            TBRRDAT[7:0] <= RAM_DI;
            // if (started && BRR_VOICE == 3)
            //     $fdisplay(32'h80000002, "BRR datal=%x", RAM_DI);
        end
        RS_ECHORDL,RS_ECHORDH : begin
            if (STEP == 22)
                LR = 0;
            else
                LR = 1;

            if (RS == RS_ECHORDL)
                ECHO_DATA_TEMP <= RAM_DI[7:1];
            else begin
                ECHO_BUF[LR][0] <= ECHO_BUF[LR][1];
                ECHO_BUF[LR][1] <= ECHO_BUF[LR][2];
                ECHO_BUF[LR][2] <= ECHO_BUF[LR][3];
                ECHO_BUF[LR][3] <= ECHO_BUF[LR][4];
                ECHO_BUF[LR][4] <= ECHO_BUF[LR][5];
                ECHO_BUF[LR][5] <= ECHO_BUF[LR][6];
                ECHO_BUF[LR][6] <= ECHO_BUF[LR][7];
                ECHO_BUF[LR][7] <= {RAM_DI, ECHO_DATA_TEMP};
            end
        end
        default : ;
        endcase
    end
end

assign RAM_D = RAM_DO;
assign RAM_DI = RAM_Q;

assign RAM_WE_N = ~RAM_WE;
assign RAM_OE_N = ~RAM_OE;
assign RAM_CE_N = ~RAM_CE;

reg signed [15:0] BRR_BUF [128];     // [0:7][0:11]

always @(posedge CLK) begin
    if (BRR_BUF_WE)
        BRR_BUF[BRR_BUF_ADDR_A] <= BRR_BUF_DI;
    else
        BRR_BUF_DO <= BRR_BUF[BRR_BUF_ADDR_A];
end
always @(posedge CLK) begin
    BRR_BUF_GAUSS_DO <= BRR_BUF[BRR_BUF_ADDR_B];
end

always @(posedge CLK) begin : brr_decode
    logic [1:0] FILTER;
    logic [3:0] SCALE;
    logic signed [15:0] SOUT;
    logic signed [16:0] P1;
    logic signed [16:0] SF;
    logic signed [15:0] S;   // original sample -8 ~ 7
    logic [3:0] BRR_BUF_ADDR_PREV;
    logic [3:0] BRR_BUF_ADDR_NEXT;

    if (~RST_N) begin
        BRR_BUF_ADDR <= '{8{4'b0}};
        BRR_BUF_WE <= 0;
        BD_STATE <= BD_IDLE;
    end else begin
        BRR_BUF_WE <= 0;
        if (ENABLE && CE) begin
            // https://snes.nesdev.org/wiki/BRR_samples
            if (BDS.S != BDS_IDLE && BRR_DECODE_EN) begin
                FILTER = TBRRHDR[3:2];
                SCALE = TBRRHDR[7:4];

                case (BDS.S)
                BDS_SMPL0:      // Each sample nibble is a signed 4-bit value in the range of -8 to +7.
                    S = {{13{TBRRDAT[15]}}, TBRRDAT[14], TBRRDAT[13], TBRRDAT[12]};
                BDS_SMPL1:
                    S = {{13{TBRRDAT[11]}}, TBRRDAT[10], TBRRDAT[9],  TBRRDAT[8]};
                BDS_SMPL2:
                    S = {{13{TBRRDAT[7]}}, TBRRDAT[6], TBRRDAT[5], TBRRDAT[4]};
                BDS_SMPL3:
                    S = {{13{TBRRDAT[3]}}, TBRRDAT[2], TBRRDAT[1], TBRRDAT[0]};
                default: ;
                endcase

                if (SCALE <= 12) SR = (S << SCALE) >>> 1;
                else SR = S & 16'hf800;
                // if (SCALE <= 12)
                //     SR = (S << SCALE) >>> 1;
                // else
                //     SR = S & 16'hF800;
                BD_VOICE <= BDS.V;
                BRR_BUF_ADDR_A[6:4] <= BDS.V;
                BRR_BUF_ADDR_A[3:0] <= BRR_BUF_ADDR[BDS.V];
                BD_STATE <= BD_WAIT;
            end
        end

        case (BD_STATE)
        BD_WAIT: begin
            BD_STATE <= BD_P0;
            BRR_BUF_ADDR_PREV = BRR_BUF_ADDR[BD_VOICE];
            if (BRR_BUF_ADDR_PREV == 0)
                BRR_BUF_ADDR_PREV = 11;
            else
                BRR_BUF_ADDR_PREV = BRR_BUF_ADDR_PREV - 1;
            BRR_BUF_ADDR_A[3:0] <= BRR_BUF_ADDR_PREV;
        end
        BD_P0: begin
            BD_STATE <= BD_P1;
            P0 <= 17'(BRR_BUF_DO);
        end
        BD_P1: begin
            // Filter application. This is Tricky.
            // - Easy to cause overflows
            // - Needs lots of () as shifting is lower-precedence than +/-
            P1 = 17'(BRR_BUF_DO) >>> 1;

            case (FILTER)
            2'b00 :
                SF = 17'(SR);
            2'b01 :
                // SR + P0*15/32
                // output += output[now-1] * 15/16
                SF = 17'(SR) + (P0 >>> 1) + ((-P0) >>> 5);
            2'b10 :
                // SR + P0*61/64 - P1*15/16
                // output += output[now-1] * 61/32 - output[now-2] * 15/16;
                SF = 17'(SR)
                    + P0 + ((-P0 * 32'sd3) >>> 6)
                    - P1 + (P1 >>> 4);
            default :
                // SR + P0*115/128 - P1*13/16
                // output += output[now-1] * 115/64 - output[now-2] * 13/16;
                SF = 17'(SR)
                    + P0 + ((-P0 * 32'sd13) >>> 7)
                    - P1 + ((P1 * 32'sd3) >>> 4);
            endcase

            SOUT = CLAMP16(SF) << 1;
            if (BRR_BUF_ADDR[BD_VOICE] == 4'd11)
                BRR_BUF_ADDR_NEXT = 0;
            else
                BRR_BUF_ADDR_NEXT = BRR_BUF_ADDR[BD_VOICE] + 1;
            BRR_BUF_ADDR_A[3:0] <= BRR_BUF_ADDR_NEXT;
            BRR_BUF_DI <= SOUT;
            BRR_BUF_WE <= 1;
            BRR_BUF_ADDR[BD_VOICE] <= BRR_BUF_ADDR_NEXT;

            // $fdisplay(32'h80000002, "BRR decoded[%d]=%x", BRR_BUF_ADDR_NEXT, SOUT);

            BD_STATE <= BD_IDLE;
        end
        default: ;
        endcase
    end
end

assign BRR_BUF_ADDR_B_NEXT = BRR_BUF_ADDR_B[3:0] == 4'b1011 ? 4'b0 :
                            (BRR_BUF_ADDR_B[3:0] + 1);

always @(posedge CLK) begin : main_process
    logic signed [15:0] GSUM, OUT_TEMP;
    logic signed [16:0] SUM3;
    logic signed [16:0] VOL_TEMP;
    logic [3:0] BB_POS;
    logic [4:0] BB_POS0;
    logic [15:0] NEW_INTERP_POS;
    logic signed [12:0] ENV_TEMP;
    logic signed [12:0] ENV_TEMP2;
    logic [4:0] ENV_RATE;
    logic [2:0] GAIN_MODE;
    logic [2:0] NEW_KON_CNT;
    logic [4:0] NOISE_RATE;
    logic [14:0] NEW_NOISE;

    if (~RST_N) begin
        GTBL_ADDR <= 0;
        BRR_ADDR <= '{8{16'b0}};
        BRR_OFFS <= '{8{3'b0}};
        INTERP_POS <= '{8{16'b0}};
        TDIR <= 8'b0;
        TDIR_ADDR <= 16'b0;
        TADSR1 <= 8'b0;
        TADSR2 <= 8'b0;
        TSRCN <= 8'b0;
        TPITCH <= 0;
        ENV <= '{8{12'b0}};
        ENV_MODE <= '{8{EM_RELEASE}};
        BENT_INC_MODE <= 8'b0;
        TOUT <= 16'b0;
        TKON <= 8'b0;
        TKOFF <= 8'b0;
        KON_CNT <= '{8{3'b0}};
        WKON <= 8'b0;
        RST_FLG <= 1'b1;
        MUTE_FLG <= 1'b1;
        ECEN_FLG <= 1'b1;
        EVEN_SAMPLE <= 1'b1;
        OUTL <= 16'b0;
        OUTR <= 16'b0;
        MOUT <= '{2{16'b0}};
        EOUT <= '{2{16'b0}};
        TESA <= 8'b0;
        TNON <= 8'b0;
        NOISE <= {1'b1, 14'b0};
        TEON <= 8'b0;
        ECHO_POS <= 15'b0;
        ECHO_LEN <= 15'b0;
        ECHO_FFC <= '{8{8'b0}};
        ECHO_FIR <= '{2{16'b0}};
        FFC_CNT <= 3'b0;
        ECHO_WR_EN <= 1'b0;
        ENDX <= 8'b0;
        ENDX_BUF <= 8'b0;
        OUTX_OUT <= 8'b0;
        TENVX <= '{8{8'b0}};
        ENVX_OUT <= 0;
        BRR_DECODE_EN <= 1'b0;
        BRR_END <= 0;
        GS_STATE <= GS_IDLE;
    end else begin
        GTBL_DO <= GTBL[GTBL_ADDR];

        if (DBG_DAT_WR && DBG_REG[7] == 1'b0) begin
            if (DBG_REG[6:0] == 7'b1101100) begin          // 6C: FLG
                RST_FLG <= DBG_DAT_IN[7];
                MUTE_FLG <= DBG_DAT_IN[6];
                ECEN_FLG <= DBG_DAT_IN[5];
            end else if (DBG_REG[6:0] == 7'b1001100) begin // 4C: KON
                WKON <= DBG_DAT_IN & ~MUTE_MASK;
            end else if (DBG_REG[6:0] == 7'b1011101) begin // 5D: DIR
                TDIR <= DBG_DAT_IN;
            end else if (DBG_REG[6:0] == 7'b1101101) begin // 6D: ESA
                TESA <= DBG_DAT_IN;
            end
        end else if (CE) begin
            if (SMP_EN_INT && !RI[7] && SMP_A == 16'h00F3 && ~SMP_WE_N) begin
                // $fdisplay(32'h80000002, "SMP reg[%08x] <= %08x", RI, SMP_DO);
                if (RI[6:0] == 7'b1001100) begin            // $4C: KON
                    WKON <= SMP_DO & ~MUTE_MASK;
;
                    // if (SMP_DO != 0)
                    //     started <= 1;
                end else if (RI[6:0] == 7'b1101100) begin   // $6C: FLG
                    RST_FLG <= SMP_DO[7];
                    MUTE_FLG <= SMP_DO[6];
                    ECEN_FLG <= SMP_DO[5];
                end else if (RI[6:0] == 7'b1111100) begin   // $7C: ENDX
                    ENDX_BUF <= 8'b0;
                    ENDX <= 0;
                end else if (RI[3:0] == 4'b1000)            // ENVX
                    ENVX_OUT <= 0;
                else if (RI[3:0] == 4'b1001)                // OUTX
                    OUTX_OUT <= 0;
            end

            NEW_KON_CNT = KON_CNT[INS.V] - 1;
            case (INS.S)
            IS_ENV : begin      // STEP 1.2, 4.2, 7.2, 10.2, 13.2, 16.2, 19.2, 30.2
                LAST_ENV <= ENV[INS.V];

                if (KON_CNT[INS.V] != 0) begin
                    if (KON_CNT[INS.V] == 5) begin
                        BRR_ADDR[INS.V] <= BRR_NEXT_ADDR;     // Set new BRR_ADDR
                        BRR_OFFS[INS.V] <= 3'b0;
                    end

                    INTERP_POS[INS.V] <= 16'b0;
                    if (NEW_KON_CNT[1:0] != 2'b0)               // KON_CNT = 4 3 2
                        INTERP_POS[INS.V] <= 16'h4000;

                    ENV[INS.V] <= 0;
                    LAST_ENV <= 0;
                    TPITCH <= 0;
                end else
                    if (TPMON[INS.V])                       // Set pitch modulation, uses 27x18 multiplier
                        TPITCH <= signed'(TPITCH) + 15'(32'(16'(TOUT >>> 5) * signed'(TPITCH)) >>> 10);

                if (RST_FLG || (TBRRHDR[1:0] == 2'b01 && KON_CNT[INS.V] != 5)) begin
                    ENV_MODE[INS.V] <= EM_RELEASE;
                    ENV[INS.V] <= 0;
                end

                if (EVEN_SAMPLE && TKON[INS.V])
                    KON_CNT[INS.V] <= 3'b101;               // Start KON process on even sample
                else if (KON_CNT[INS.V] != 0)
                    KON_CNT[INS.V] <= NEW_KON_CNT;          // KON_CNT --

                if (EVEN_SAMPLE) begin
                    if (TKON[INS.V])
                        ENV_MODE[INS.V] <= EM_ATTACK;       // Start with ATTACK
                    else if (TKOFF[INS.V])
                        ENV_MODE[INS.V] <= EM_RELEASE;      // End with RELEASE
                end

                TENVX[INS.V] <= {1'b0, ENV[INS.V][10:4]};
            end

            IS_ENV2 : begin     // STEP 1.3, 4.3, 7.3, 10.3, 13.3, 16.3, 19.3, 30.3
                BB_POS = {1'b0, INTERP_POS[INS.V][14:12]};
                BB_POS0 = {1'b0, BB_POS + BRR_BUF_ADDR[INS.V] + 4'd1};
                if (BB_POS0 > 11)
                    BB_POS0 = BB_POS0 - 12;
                GTBL_ADDR <= {1'b0, ~INTERP_POS[INS.V][11:4]};
                G_VOICE <= INS.V;
                BRR_BUF_ADDR_B[6:4] <= INS.V;
                BRR_BUF_ADDR_B[3:0] <= BB_POS0[3:0];
                GS_STATE <= GS_WAIT;
            end

            default: ;
            endcase

            case (VS.S)        // pipeline to compute output from samples
            VS_ADSR1 : begin
                TADSR1 <= REGS_DO;

                if (VS.V == 0)
                    ECHO_ADDR <= {TESA, 8'h00} + ECHO_POS;
            end

            VS_PITCHL :
                TPITCH[7:0] <= REGS_DO;

            VS_PITCHH :  begin
                TPITCH[14:8] <= {1'b0, REGS_DO[5:0]};
                OUTX_OUT <= TOUT[15:8];
            end

            VS_ADSR2 :
                TADSR2 <= REGS_DO;

            VS_SRCN : begin
                TSRCN <= REGS_DO;
                TDIR_ADDR <= {TDIR, 8'b0} + 16'({TSRCN, 2'b0});
            end

            VS_VOLL : begin
                VOL_TEMP = 17'(24'(TOUT * signed'(REGS_DO)) >>> 7);
                //   VOL_TEMP = 17'(24'(TOUT * REGS_DO) >>> 7);
                MOUT[0] <= CLAMP16(17'(MOUT[0]) + VOL_TEMP);
                if (TEON[VS.V])
                    EOUT[0] <= CLAMP16(17'(EOUT[0]) + VOL_TEMP);

                BRR_END <= 0;
                BRR_DECODE_EN <= 1'b0;
                if (INTERP_POS[VS.V][15:14] != 2'b00) begin     // >= 4000
                    BRR_DECODE_EN <= 1'b1;
                    BRR_OFFS[VS.V] <= BRR_OFFS[VS.V] + 2;
                    if (BRR_OFFS[VS.V] == 6) begin
                        if (TBRRHDR[0]) begin      // end bit ON
                            BRR_ADDR[VS.V] <= BRR_NEXT_ADDR;
                            BRR_END[VS.V] <= 1'b1;
                        end else
                            BRR_ADDR[VS.V] <= BRR_ADDR[VS.V] + 9;
                    end
                end

                NEW_INTERP_POS = {2'b0, INTERP_POS[VS.V][13:0]} + {1'b0, TPITCH};
                if (~NEW_INTERP_POS[15])
                    INTERP_POS[VS.V] <= NEW_INTERP_POS;
                else
                    INTERP_POS[VS.V] <= 16'h7FFF;
            end

            VS_VOLR : begin
                VOL_TEMP = 17'(24'(TOUT * signed'(REGS_DO)) >>> 7);
                MOUT[1] <= CLAMP16(17'(MOUT[1]) + VOL_TEMP);
                if (TEON[VS.V])
                    EOUT[1] <= CLAMP16(17'(EOUT[1]) + VOL_TEMP);

                ENDX_BUF <= ENDX | BRR_END;
                if (KON_CNT[VS.V] == 5)
                    ENDX_BUF[VS.V] <= 1'b0;
            end

            VS_MVOLL :
                MOUT[0] <= shortint'(24'(MOUT[0] * signed'(REGS_DO)) >>> 7);

            VS_MVOLR :
                MOUT[1] <= shortint'(24'(MOUT[1] * signed'(REGS_DO)) >>> 7);

            VS_EVOLL : begin
                if (MUTE_FLG)
                    OUTL <= 16'b0;
                else    // VOL_OUT
                    OUTL <= CLAMP16(17'(MOUT[0]) +
                                17'(24'(ECHO_FIR[0] * signed'(REGS_DO)) >>> 7) );
                MOUT[0] <= 16'b0;
            end

            VS_EVOLR : begin
                if (MUTE_FLG)
                    OUTR <= 16'b0;
                else    // VOL_OUT
                    OUTR <= CLAMP16( 17'(MOUT[1]) +
                                17'(24'(ECHO_FIR[1] * signed'(REGS_DO)) >>> 7) );
                MOUT[1] <= 16'b0;
                ECHO_FIR[0] <= 16'b0;
                ECHO_FIR_TEMP[0] <= 0;
                ECHO_FIR[1] <= 16'b0;
                ECHO_FIR_TEMP[1] <= 0;
            end

            VS_DIR :
                TDIR <= REGS_DO;

            VS_KON :
                if (EVEN_SAMPLE)
                    WKON <= WKON & ~TKON;

            VS_KOFF :
                if (EVEN_SAMPLE) begin
                    TKON <= WKON;
                    TKOFF <= REGS_DO | DBG_VMUTE;
                end

            VS_PMON :
                TPMON <= {REGS_DO[7:1], 1'b0};

            VS_NON :
                TNON <= REGS_DO;

            VS_FLG : begin
                NOISE_RATE = REGS_DO[4:0];
                NEW_NOISE = {NOISE[0] ^ NOISE[1], 14'b0} | {1'b0, NOISE[14:1]};
                if (GCOUNT_TRIGGER(NOISE_RATE))
                    NOISE <= NEW_NOISE;

                EOUT[0] <= 16'b0;
                EOUT[1] <= 16'b0;
            end

            VS_EON : begin
                TEON <= REGS_DO;
                ECHO_WR_EN <= ~ECEN_FLG;
            end

            VS_EDL :
                if (ECHO_POS == 0) begin
                    ECHO_LEN <= {REGS_DO[3:0], 11'b0};
                end

            VS_ESA : begin
                TESA <= REGS_DO;
                EVEN_SAMPLE <=  ~EVEN_SAMPLE;

                if (ECHO_POS + 4 >= ECHO_LEN)
                    ECHO_POS <= 0;
                else
                    ECHO_POS <= ECHO_POS + 4;
                ECHO_WR_EN <= ~ECEN_FLG;
            end

            VS_FIR0, VS_FIR1, VS_FIR2, VS_FIR3,
            VS_FIR4, VS_FIR5, VS_FIR6, VS_FIR7 :
                ECHO_FFC[VS.V] <= REGS_DO;

            VS_EFB : begin
                EOUT[0] <= CLAMP16(17'(EOUT[0]) + 17'(24'(ECHO_FIR[0] * signed'(REGS_DO)) >>> 7)) & 16'hFFFE;
                EOUT[1] <= CLAMP16(17'(EOUT[1]) + 17'(24'(ECHO_FIR[1] * signed'(REGS_DO)) >>> 7)) & 16'hFFFE;
            end

            VS_ENVX : ;

            VS_OUTX : begin
                ENDX <= ENDX_BUF;
                ENVX_OUT <= TENVX[VS.V];
            end

            VS_ECHO : ;

            default : ;
            endcase

            if (STEP == 24 || STEP == 25) begin
                ECHO_FIR_TEMP[0] <= ECHO_FIR_TEMP[0] +
                        16'(23'(signed'(ECHO_BUF[0][FFC_CNT]) * ECHO_FFC[FFC_CNT]) >>> 6); // and x"FFFE"
                ECHO_FIR_TEMP[1] <= ECHO_FIR_TEMP[1] +
                        16'(23'(signed'(ECHO_BUF[1][FFC_CNT]) * ECHO_FFC[FFC_CNT]) >>> 6); // and x"FFFE"
                if (FFC_CNT == 7) begin
                    ECHO_FIR[0] <= CLAMP16(17'(ECHO_FIR_TEMP[0]) + 17'(shortint'(23'(signed'(ECHO_BUF[0][FFC_CNT]) * ECHO_FFC[FFC_CNT]) >>> 6))) & 16'hFFFE;
                    ECHO_FIR[1] <= CLAMP16(17'(ECHO_FIR_TEMP[1]) + 17'(shortint'(23'(signed'(ECHO_BUF[1][FFC_CNT]) * ECHO_FFC[FFC_CNT]) >>> 6))) & 16'hFFFE;
                end
                FFC_CNT <= FFC_CNT + 1;
            end
        end // if (CE)

        case (GS_STATE)
        GS_WAIT: begin
            GS_STATE <= GS_BRR0;
            BRR_BUF_ADDR_B[3:0] <= BRR_BUF_ADDR_B_NEXT;
            GTBL_ADDR[8] <= 1;
        end

        GS_BRR0: begin
            SUM012 <= 17'(28'(GTBL_DO * BRR_BUF_GAUSS_DO) >> 11);
            BRR_BUF_ADDR_B[3:0] <= BRR_BUF_ADDR_B_NEXT;
            GTBL_ADDR[7:0] <= ~GTBL_ADDR[7:0];
            GS_STATE <= GS_BRR1;
        end

        GS_BRR1: begin
            SUM012 <= SUM012 + 17'(28'(GTBL_DO * BRR_BUF_GAUSS_DO) >> 11);
            BRR_BUF_ADDR_B[3:0] <= BRR_BUF_ADDR_B_NEXT;
            GTBL_ADDR[8] <= 0;
            GS_STATE <= GS_BRR2;
        end

        GS_BRR2: begin
            SUM012 <= SUM012 + 17'(28'(GTBL_DO * BRR_BUF_GAUSS_DO) >> 11);
            GS_STATE <= GS_BRR3;
        end

        GS_BRR3: begin
            SUM3 = 17'(28'(GTBL_DO * BRR_BUF_GAUSS_DO) >> 11);

            GSUM = CLAMP16(17'($signed(SUM012[15:0])) + SUM3);
            // nand2mario: the upstream code is probably wrong...  SUM012 is 17 bits
            // GSUM := CLAMP16( resize(SUM012(15)&SUM012(15 downto 0) + SUM3, 17) );
            // GSUM = CLAMP16(17'({SUM012[15],SUM012[15:0]} + SUM3));

            if (~TNON[G_VOICE])
                OUT_TEMP = GSUM & 16'hFFFE;
            else
                OUT_TEMP = {NOISE, 1'b0};

            // env apply
            TOUT <= 16'(28'(OUT_TEMP * LAST_ENV) >>> 11) & 16'hFFFE;

            // envelope
            if (KON_CNT[G_VOICE] == 0) begin
                if (ENV_MODE[G_VOICE] == EM_RELEASE) begin
                    ENV_TEMP2 = 13'(ENV[G_VOICE]) - 8;
                    if (ENV_TEMP2 < 0) begin
                        ENV_TEMP2 = 0;
                    end
                    ENV[G_VOICE] <= 12'(ENV_TEMP2);
                    ENV_RATE = 5'b11111;
                end else begin
                    if (TADSR1[7]) begin
                        if (ENV_MODE[G_VOICE] == EM_DECAY || ENV_MODE[G_VOICE] == EM_SUSTAIN) begin
                            ENV_TEMP = 13'(ENV[G_VOICE]) - ((ENV[G_VOICE] - 1) >>> 8) - 1;
                            if (ENV_MODE[G_VOICE] == EM_DECAY)
                                ENV_RATE = {1'b1, TADSR1[6:4], 1'b0};
                            else
                                ENV_RATE = TADSR2[4:0];
                        end else begin
                            ENV_RATE = {TADSR1[3:0], 1'b1};
                            if (ENV_RATE != 31)
                                ENV_TEMP = 13'(ENV[G_VOICE]) + 13'h020;
                            else
                                ENV_TEMP = 13'(ENV[G_VOICE]) + 13'h400;
                        end
                    end else begin
                        GAIN_MODE = TADSR2[7:5];
                        if (~GAIN_MODE[2]) begin
                            ENV_TEMP = 13'({TADSR2[6:0], 4'b0000});
                            ENV_RATE = 5'b11111;
                        end else begin
                            ENV_RATE = TADSR2[4:0];
                            if (GAIN_MODE[1:0] == 2'b00)
                                ENV_TEMP = 13'(ENV[G_VOICE]) - 13'h020;
                            else if (GAIN_MODE[1:0] == 2'b01)
                                ENV_TEMP = 13'(ENV[G_VOICE]) - ((ENV[G_VOICE] - 1) >>> 8) - 1;
                            else if (GAIN_MODE[1:0] == 2'b10)
                                ENV_TEMP = 13'(ENV[G_VOICE]) + 13'h020;
                            else begin
                                if (BENT_INC_MODE[G_VOICE] == 1'b0)
                                    ENV_TEMP = 13'(ENV[G_VOICE]) + 13'h020;
                                else
                                    ENV_TEMP = 13'(ENV[G_VOICE]) + 13'h008;
                            end
                        end
                    end

                    if (unsigned'(ENV_TEMP[10:0]) >= 11'h600 || ENV_TEMP[12:11] != 2'b00)
                        BENT_INC_MODE[G_VOICE] <= 1;
                    else
                        BENT_INC_MODE[G_VOICE] <= 0;

                    if (ENV_TEMP[10:8] == TADSR2[7:5] && ENV_MODE[G_VOICE] == EM_DECAY)
                        ENV_MODE[G_VOICE] <= EM_SUSTAIN;

                    if (ENV_TEMP[12:11] != 2'b00) begin
                        if (ENV_TEMP < 0)
                            ENV_TEMP2 = 13'b0;
                        else
                            ENV_TEMP2 = 13'b0_0111_1111_1111;
                        if (ENV_MODE[G_VOICE] == EM_ATTACK)
                            ENV_MODE[G_VOICE] <= EM_DECAY;
                    end else
                        ENV_TEMP2 = ENV_TEMP;

                    if (GCOUNT_TRIGGER(ENV_RATE))
                        ENV[G_VOICE] <= 12'(ENV_TEMP2);
                end
            end else begin
                ENV[G_VOICE] <= 12'b0;
                BENT_INC_MODE[G_VOICE] <= 0;
            end // if (KON...)
            GS_STATE <= GS_IDLE;
        end

        default: ;
        endcase
    end
end

always @(posedge CLK) begin : gcount
    if (~RST_N) begin
        GCNT_BY1 <= 12'b0;
        GCNT_BY3 <= 12'h410;
        GCNT_BY5 <= 12'h218;
    end else if (ENABLE && CE) begin
        if (STEP == 30 && SUBSTEP == 1) begin
            if (GCNT_BY3[1:0] == 2'b00)
                GCNT_BY3[1:0] <= 2'b10;
            else
                GCNT_BY3 <= GCNT_BY3 + 1;

            if (GCNT_BY5[2:0] == 3'b000)
                GCNT_BY5[2:0] <= 3'b100;
            else
                GCNT_BY5 <= GCNT_BY5 + 1;

            GCNT_BY1 <= GCNT_BY1 + 1;
        end
    end
end

always @(posedge CLK) begin : output2audio
    if (~RST_N) begin
        OUTPUT <= 32'b0;
        SND_RDY <= 1'b0;
        AUDIO_L <= 16'b0;
        AUDIO_R <= 16'b0;
    end else begin
        SND_RDY <= 1'b0;        // ensure pulse
        if (ENABLE && CE) begin
            if (SUBSTEP == 3) begin
                OUTPUT <= {OUTPUT[30:0], 1'b0};
                if (STEP == 31) begin
                    OUTPUT <= {OUTL, OUTR};
                    AUDIO_L <= OUTL;
                    AUDIO_R <= OUTR;
                    SND_RDY <= 1'b1;
                end
            end
        end
    end
end

/*
assign LRCK =  ~STEP_CNT[4];
assign BCK = SUBSTEP_CNT[1];
assign SDAT = OUTPUT[31];
*/

endmodule


// ---- upstream: src/smp.v ----
// SNES sound processor module

module SMP (
    input CLK,
    input RST_N,
    input CE,
    input ENABLE,
    input SYSCLKF_CE,

    // SMP to memory
    output [15:0] A,
    input [7:0] DI,
    output [7:0] DO,
    output WE_N,

    // PA from CPU
    input [1:0] PA,
    input PARD_N,
    input PAWR_N,
    input [7:0] CPU_DI,
    output [7:0] CPU_DO,
    input CS,
    input CS_N,

    // Debug
    input [7:0] DBG_REG,
    input [7:0] DBG_DAT_IN,
    output reg [7:0] DBG_SMP_DAT,
    output [7:0] DBG_CPU_DAT,
    input DBG_CPU_DAT_WR,
    input DBG_SMP_DAT_WR,
    output BRK_OUT
);

reg [7:0] SPC700_D_IN, SPC700_D_OUT;
wire [15:0] SPC700_A;
wire SPC700_R_WN;
wire SPC700_CE;
reg TIMER_CE;

reg [7:0] CPUI[0:3];
reg [7:0] CPUO[0:3];
reg PAWR_N_OLD;

reg [7:0] TEST;
reg [1:0] CLK_SPEED;
reg [1:0] TM_SPEED;
reg TIMERS_ENABLE, TIMERS_DISABLE;
reg RAM_WRITE_EN;
reg [2:0] TM_EN;
reg IPL_EN;
reg [7:0] T0DIV;
reg [7:0] T1DIV;
reg [7:0] T2DIV;
reg [3:0] T0OUT;
reg [3:0] T1OUT;
reg [3:0] T2OUT;
reg [7:0] AUX [2];

reg [1:0] RESET_PORT;
reg [8:0] TM01_CNT;
reg [5:0] TM2_CNT;
reg [7:0] T0_CNT, T1_CNT, T2_CNT;
wire RESET01, RESET23;
localparam [7:0] IPLROM[0:63] = '{8'hcd,8'hef,8'hbd,8'he8,8'h00,8'hc6,8'h1d,8'hd0,8'hfc,8'hc6,8'h8f,8'haa,8'hf4,8'h8f,8'hbb,8'hf5,8'h78,8'hcc,8'hf4,8'hd0,8'hfb,8'hba,8'hf6,8'hda,8'h00,8'hfa,8'hf4,8'hf4,8'he4,8'hf5,8'hf0,8'h1b,8'h8d,8'h00,8'h7e,8'hf4,8'hd0,8'hfc,8'he4,8'hf5,8'hcb,8'hf4,8'hd7,8'h00,8'hfc,8'hf0,8'h08,8'h7e,8'hf4,8'hf0,8'hf3,8'h10,8'hfa,8'h2f,8'hde,8'hab,8'h01,8'h2f,8'hf4,8'h1f,8'h00,8'h00,8'hc0,8'hff};

assign SPC700_CE = ENABLE & CE;

always @(posedge CLK) begin
    if (RST_N == 1'b0) begin
        CPUI <= '{4{8'b0}};
        PAWR_N_OLD <= 1'b1;
    end else begin
        PAWR_N_OLD <= PAWR_N;
        if (~PAWR_N && PAWR_N_OLD && CS && ~CS_N) begin
            // $2140-2143
            // PA: CPUI[ 01xx_xxPA ]
            CPUI[PA] <= CPU_DI;
;
        end
        if (SPC700_CE) begin
            if (SPC700_A == 16'h00F1 && ~SPC700_R_WN) begin
                if (SPC700_D_OUT[4]) begin
                    CPUI[0] <= 8'b0;
                    CPUI[1] <= 8'b0;
                end
                if (SPC700_D_OUT[5]) begin
                    CPUI[2] <= 0;
                    CPUI[3] <= 0;
                end
            end
        end
    end
end

assign CPU_DO = CPUO[PA[1:0]];

SPC700 SPC700 (
    .CLK(CLK),
    .RST_N(RST_N),
    .RDY(SPC700_CE),
    .IRQ_N(1'b1),
    .A_OUT(SPC700_A),
    .D_IN(SPC700_D_IN),
    .D_OUT(SPC700_D_OUT),
    .WE_N(SPC700_R_WN),

    .DBG_REG(DBG_REG),
    .DBG_DAT_IN(DBG_DAT_IN),
    .DBG_DAT_OUT(DBG_CPU_DAT),
    .DBG_DAT_WR(DBG_CPU_DAT_WR),
    .BRK_OUT(BRK_OUT)
);

always @(posedge CLK) begin : spc_timers
    reg [4:0] TM_STEP;
    reg [8:0] NEW_TM01_CNT;
    reg [5:0] NEW_TM2_CNT;

    if (~RST_N) begin
        CLK_SPEED <= 0;
        TM_SPEED <= 0;
        TIMERS_ENABLE <= 1'b1;
        TIMERS_DISABLE <= 1'b0;
        RAM_WRITE_EN <= 1;
        IPL_EN <= 1'b1;
        TM_EN <= 3'b0;
        // RESET_PORT <= 2'b11;
        CPUO <= '{4{8'b0}};
        T0OUT <= 4'b0;
        T1OUT <= 4'b0;
        T2OUT <= 4'b0;
        T0DIV <= 8'b1111_1111;
        T1DIV <= 8'b1111_1111;
        T2DIV <= 8'b1111_1111;
        AUX <= '{2{8'b0}};

        TM01_CNT <= 0;
        TM2_CNT <= 0;
        T0_CNT <= 8'b0;
        T1_CNT <= 8'b0;
        T2_CNT <= 8'b0;

        TIMER_CE <= 0;
    end else begin
        TIMER_CE <= 0;
        if (~ENABLE) begin
            if (DBG_SMP_DAT_WR) begin
                case (DBG_REG)
                    8'h01: begin
                        IPL_EN <= DBG_DAT_IN[7];
                        TM_EN <= DBG_DAT_IN[2:0];
                        RESET_PORT <= DBG_DAT_IN[5:4];
                    end
                    8'h0A: begin
                        T0DIV <= DBG_DAT_IN;
                    end
                    8'h0B: begin
                        T1DIV <= DBG_DAT_IN;
                    end
                    8'h0C: begin
                        T2DIV <= DBG_DAT_IN;
                    end
                    default: begin
                    end
                endcase
            end
        end else if (SPC700_CE) begin
            TIMER_CE <= 1;
            if (SPC700_A[15:4] == 12'h00F) begin
                if (~SPC700_R_WN) begin
                    case (SPC700_A[3:0])
                        4'h0: begin
                            CLK_SPEED <= SPC700_D_OUT[7:6];
                            TM_SPEED <= SPC700_D_OUT[5:4];
                            TIMERS_ENABLE <= SPC700_D_OUT[3];
                            RAM_WRITE_EN <= SPC700_D_OUT[1];
                            TIMERS_DISABLE <= SPC700_D_OUT[0];
                        end
                        4'h1: begin
                            IPL_EN <= SPC700_D_OUT[7];
                            // RESET_PORT <= SPC700_D_OUT[5:4];
                            TM_EN <= SPC700_D_OUT[2:0];
                            if (SPC700_D_OUT[0] && TM_EN[0] == 1'b0) begin
                                T0OUT  <= 4'b0;
                                T0_CNT <= 8'b0;
                            end
                            if (SPC700_D_OUT[1] && TM_EN[1] == 1'b0) begin
                                T1OUT  <= 4'b0;
                                T1_CNT <= 8'b0;
                            end
                            if (SPC700_D_OUT[2] && TM_EN[2] == 1'b0) begin
                                T2OUT  <= 4'b0;
                                T2_CNT <= 8'b0;
                            end
                        end
                        4'h4, 4'h5, 4'h6, 4'h7: begin
                            CPUO[SPC700_A[1:0]] <= SPC700_D_OUT;
;
                        end
                        4'h8, 4'h9:
                            AUX[SPC700_A[0:0]] <= SPC700_D_OUT;
                        4'hA:
                            T0DIV <= SPC700_D_OUT;
                        4'hB:
                            T1DIV <= SPC700_D_OUT;
                        4'hC:
                            T2DIV <= SPC700_D_OUT;
                        default: begin
                        end
                    endcase
                end else begin
                    case (SPC700_A[3:0])
                        4'hD: T0OUT <= 4'b0;
                        4'hE: T1OUT <= 4'b0;
                        4'hF: T2OUT <= 4'b0;
                        default: ;
                    endcase
                end
            end
        end

        if (TIMER_CE) begin
            TM_STEP = (5'b00001 << CLK_SPEED) + (5'b00010 << TM_SPEED);
            NEW_TM01_CNT = TM01_CNT + 9'(TM_STEP);
            if (NEW_TM01_CNT[8:7] == 2'b11) begin
                TM01_CNT <= NEW_TM01_CNT & 9'b001111111;
                if (TM_EN[0] && TIMERS_ENABLE && ~TIMERS_DISABLE) begin
                    T0_CNT <= T0_CNT + 1;
                    if (T0_CNT + 8'd1 == T0DIV) begin
                        T0_CNT <= 0;
                        T0OUT  <= T0OUT + 1;
                    end
                end
                if (TM_EN[1] && TIMERS_ENABLE && ~TIMERS_DISABLE) begin
                    T1_CNT <= T1_CNT + 1;
                    if (T1_CNT + 8'd1 == T1DIV) begin
                        T1_CNT <= 0;
                        T1OUT  <= T1OUT + 1;
                    end
                end
            end else
                TM01_CNT <= NEW_TM01_CNT;

            NEW_TM2_CNT = TM2_CNT + TM_STEP;
            if (NEW_TM2_CNT[5:4] == 2'b11) begin
                TM2_CNT <= NEW_TM2_CNT & 6'b001111;
                if (TM_EN[2] && TIMERS_ENABLE && ~TIMERS_DISABLE) begin
                    T2_CNT <= T2_CNT + 1;
                    if (T2_CNT + 8'd1 == T2DIV) begin
                        T2_CNT <= 0;
                        T2OUT  <= T2OUT + 1;
                    end
                end
            end else
                TM2_CNT <= NEW_TM2_CNT;
        end
    end
end

always @* begin
    if (SPC700_A[15:4] == 12'h00F) begin
        case (SPC700_A[3:0])
            4'h2, 4'h3:        //DSPADDR/DSPDATA
                SPC700_D_IN = DI;
            4'h4, 4'h5, 4'h6, 4'h7:
                SPC700_D_IN = CPUI[SPC700_A[1:0]];
            4'h8, 4'h9:
                SPC700_D_IN = AUX[SPC700_A[0]];
            4'hD:
                SPC700_D_IN = {4'h0, T0OUT};
            4'hE:
                SPC700_D_IN = {4'h0, T1OUT};
            4'hF:
                SPC700_D_IN = {4'h0, T2OUT};
            default:
                SPC700_D_IN = 8'b0;
        endcase
    end else if (SPC700_A >= 16'hFFC0 && IPL_EN)
        SPC700_D_IN = IPLROM[SPC700_A[5:0]];
    else
        SPC700_D_IN = DI;
end

assign A = SPC700_A;
assign WE_N = SPC700_R_WN;
assign DO = SPC700_D_OUT;

always @* begin
    case (DBG_REG)
        8'h00: DBG_SMP_DAT = CPUI[0];
        8'h01: DBG_SMP_DAT = CPUI[1];
        8'h02: DBG_SMP_DAT = CPUI[2];
        8'h03: DBG_SMP_DAT = CPUI[3];
        8'h04: DBG_SMP_DAT = CPUO[0];
        8'h05: DBG_SMP_DAT = CPUO[1];
        8'h06: DBG_SMP_DAT = CPUO[2];
        8'h07: DBG_SMP_DAT = CPUO[3];
        8'h08: DBG_SMP_DAT = TEST;
        8'h09: DBG_SMP_DAT = {IPL_EN, 1'b0, RESET_PORT, 1'b0, TM_EN};
        8'h0A: DBG_SMP_DAT = T0DIV;
        8'h0B: DBG_SMP_DAT = T1DIV;
        8'h0C: DBG_SMP_DAT = T2DIV;
        8'h0D: DBG_SMP_DAT = {4'b0000, T0OUT};
        8'h0E: DBG_SMP_DAT = {4'b0000, T1OUT};
        8'h0F: DBG_SMP_DAT = {4'b0000, T2OUT};
        // 8'h10:
        //   DBG_SMP_DAT = CPUI0_history[7:0];
        // 8'h11:
        //   DBG_SMP_DAT = CPUI0_history[15:8];
        // 8'h12:
        //   DBG_SMP_DAT = CPUI0_history[23:16];
        // 8'h13:
        //   DBG_SMP_DAT = CPUI0_history[31:24];

        default: DBG_SMP_DAT = 8'h00;
    endcase
end

endmodule


// ---- upstream: src/swram.v ----

module SWRAM (
    input CLK,
    input SYSCLK_CE,
    input RST_N,
    input ENABLE,

    input [23:0] CA,
    input CPURD_N,
    input CPUWR_N,
    input RAMSEL_N,

    input [7:0] PA,
    input PARD_N,
    input PAWR_N,

    input CPURD_CYC_N,  // for DMA data is read before SYSCLKR_CE
    input PARD_CYC_N,

    input  [7:0] DI,
    output [7:0] DO,

    output [16:0] RAM_A,
    output [7:0] RAM_D,
    input [7:0] RAM_Q,
    output RAM_WE_N,
    output RAM_CE_N,
    output RAM_OE_N,
    output RAM_RD_N
);

    reg [23:0] WMADD;

    always @(posedge CLK) begin
        if (~RST_N ) begin
            WMADD <= 0;
        end else begin
            if (ENABLE && SYSCLK_CE) begin
                if (~PAWR_N) begin
                    case (PA)
                        8'h80: begin
                            if (RAMSEL_N) begin
                                //check if DMA use WRAM in BUS B
                                WMADD <= WMADD + 24'd1;
                            end
                        end
                        8'h81:   WMADD[7:0] <= DI;
                        8'h82:   WMADD[15:8] <= DI;
                        8'h83:   WMADD[23:16] <= DI;
                        default: ;
                    endcase

                end else if (~PARD_N) begin
                    case (PA)
                        8'h80: begin
                            if (RAMSEL_N) begin
                                //check if DMA use WRAM in ABUS
                                WMADD <= WMADD + 24'd1;
                            end
                        end
                        default: ;
                    endcase
                end
            end
        end
    end

    assign DO = RAM_Q;

    assign RAM_D = PA == 8'h80 && RAMSEL_N == 1'b0 ? 8'hFF : DI;

    assign RAM_A = RAMSEL_N == 1'b0 ? CA[16:0] : WMADD[16:0];

    assign RAM_CE_N =   ~ENABLE ? 1'b0 :
                        ~RAMSEL_N ? 1'b0 :
                        PA == 8'h80 ? 1'b0 :
                        1'b1;

    assign RAM_OE_N =   ~ENABLE ? 1'b0 :
                        ~RAMSEL_N && ~CPURD_N ? 1'b0 :
                        PA == 8'h80 && ~PARD_N && RAMSEL_N ? 1'b0 :
                        1'b1;

    assign RAM_RD_N =   ~ENABLE ? 1'b1 :        // nand2mario: do not read WRAM when CPU disabled
                        ~RAMSEL_N && ~CPURD_CYC_N ? 1'b0 :
                        PA == 8'h80 && ~PARD_CYC_N && RAMSEL_N ? 1'b0 :
                        1'b1;

    assign RAM_WE_N =   ~ENABLE ? 1'b1 :
                        ~RAMSEL_N && ~CPUWR_N ? 1'b0 :
                        PA == 8'h80 && ~PAWR_N && RAMSEL_N ? 1'b0 :
                        1'b1;

endmodule


