module CEGen(
  input wire CLK,
  input wire RST_N,
  input wire [31:0] IN_CLK,
  input wire [31:0] OUT_CLK,
  output reg CE
);

  always @(posedge CLK) begin : P1
    reg [31:0] CLK_SUM;

    if(RST_N == 1'b0) begin
      CLK_SUM = 0;
      CE <= 1'b0;
