M_TAB[2046]={3'bXXX, 3'bXXX, 2'bXX, 3'bXXX, 2'bXX, 2'bXX, 8'bXXXXXXXX, 3'bXXX, 3'bXXX, 3'bXXX, 2'bXX, 6'bXXXXXX, 5'bXXXXX, 2'bXX, 3'bXXX, 2'bXX};

// Special entry for STATE==0
M_TAB[2047]={3'b000, 3'b000, 2'b00, 3'b000, 2'b00, 2'b00, 8'b00000000, 3'b001, 3'b000, 3'b000, 2'b00, 6'b000000, 5'b00000, 2'b00, 3'b000, 2'b11};
   end

   MicroInst_r         MI;
   ALUCtrl_r        ALUFlags;

   always @* begin
      case (MI.ALUCtrl)
      5'd0: ALUFlags = {3'b100, 3'b100, 1'b0, 1'b0};    // firstOp, secondOp, fc, w16
      5'd1: ALUFlags = {3'b100, 3'b100, 1'b0, 1'b1};
      5'd2: ALUFlags = {3'b110, 3'b100, 1'b0, 1'b0};
      5'd3: ALUFlags = {3'b111, 3'b100, 1'b0, 1'b0};
      5'd4: ALUFlags = {3'b100, 3'b000, 1'b0, 1'b0};
      5'd5: ALUFlags = {3'b100, 3'b001, 1'b0, 1'b0};
      5'd6: ALUFlags = {3'b100, 3'b010, 1'b0, 1'b0};
      5'd7: ALUFlags = {3'b100, 3'b011, 1'b0, 1'b0};
      5'd8: ALUFlags = {3'b100, 3'b111, 1'b1, 1'b0};
      5'd9: ALUFlags = {3'b100, 3'b001, 1'b1, 1'b0};
      5'd10: ALUFlags = {3'b000, 3'b100, 1'b0, 1'b0};
      5'd11: ALUFlags = {3'b010, 3'b100, 1'b0, 1'b0};
      5'd12: ALUFlags = {3'b001, 3'b100, 1'b0, 1'b0};
      5'd13: ALUFlags = {3'b011, 3'b100, 1'b0, 1'b0};
      5'd14: ALUFlags = {3'b100, 3'b101, 1'b0, 1'b0};
      5'd15: ALUFlags = {3'b100, 3'b101, 1'b1, 1'b0};
      5'd16: ALUFlags = {3'b100, 3'b110, 1'b0, 1'b0};
      default: ALUFlags = 8'b0;
      endcase
   end

    // micro code format:
    // 111_000_00_000_00_00_00000000_001_000_000_00_000000_00000_00_000_00
    // stateCtrl  loadP     addrCtrl loadPC  regAXY busCtrl      byteSel
    //     addrBus    loadT              loadSP  loadDKB   ALUCtrl  outBus
    //         addrInc   muxCtrl                                        va
    always @(posedge CLK or negedge RST_N)
    begin

        if (~RST_N)
            // MI <= M_TAB[2047];
            MI <= {3'b000, 3'b000, 2'b00, 3'b000, 2'b00, 2'b00, 8'b00000000, 3'b001, 3'b000, 3'b000, 2'b00, 6'b000000, 5'b00000, 2'b00, 3'b000, 2'b11};
        else begin

            if (EN == 1'b1) begin
                // NOTE: the previous code causes LUT to explode
                // When STATE==0, returns M_TAB[2047] = {3'b000, 3'b000, 2'b00, 3'b000, 2'b00, 2'b00, 8'b00000000, 3'b001, 3'b000, 3'b000, 2'b00, 6'b000000, 5'b00000, 2'b00, 3'b000, 2'b11}
                MI <= M_TAB[STATE == 4'b0 ? 11'd2047 : {IR, (STATE[2:0] - 3'd1)}];
            end
        end
   end
   assign M = {ALUFlags, MI.stateCtrl, MI.addrBus, MI.addrInc, MI.muxCtrl, MI.addrCtrl, MI.loadPC, MI.loadSP,
               MI.regAXY, MI.loadP, MI.loadT, MI.loadDKB, MI.busCtrl, MI.byteSel, MI.outBus, MI.va};

endmodule


// ---- upstream: src/65C816/AddrGen.v ----

module AddrGen(CLK, RST_N, EN, LOAD_PC, PCDec, GotInterrupt, ADDR_CTRL, IND_CTRL, D_IN, X, Y, D, S, T, DR, DBR, e6502, PC, AA, AB, DX, AALCarry, JumpNoOfl);
   input         CLK;
   input         RST_N;
   input         EN;
   input [2:0]   LOAD_PC;
   input         PCDec;
   input         GotInterrupt;
   input [7:0]   ADDR_CTRL;
   input [1:0]   IND_CTRL;
   input [7:0]   D_IN;
   input [15:0]  X;
   input [15:0]  Y;
   input [15:0]  D;
   input [15:0]  S;
   input [15:0]  T;
   input [7:0]   DR;
   input [7:0]   DBR;
   input         e6502;
   output [15:0] PC;
   output [16:0] AA;
   output [7:0]  AB;
   reg [7:0]     AB;
   output [15:0] DX;
   output        AALCarry;
   output        JumpNoOfl;


   reg [7:0]     AAL;
   reg [7:0]     AAH;
   reg [7:0]     DL;
   reg [7:0]     DH;
   reg           SavedCarry;
   reg           AAHCarry;

   reg [8:0]     NewAAL;
   reg [8:0]     NewAAH;
   wire [8:0]    NewAAHWithCarry;
   wire [8:0]    NewDL;
   wire [15:0]   InnerDS;

   reg [15:0]    PCr;
   reg [15:0]     PCOffset;
   reg [15:0]    NextPC;
   wire [15:0]   NewPCWithOffset;
   wire [15:0]   NewPCWithOffset16;

   wire [2:0]    AALCtrl;
   wire [2:0]    AAHCtrl;
   wire [1:0]    ABSCtrl;

   assign NewPCWithOffset16 = (PCr + PCOffset);
   assign NewPCWithOffset = PCr + { {8{DR[7]}}, DR };

   always @* begin
      case (LOAD_PC)
         3'b000 :
            NextPC = PCr;
         3'b001 :
            if (GotInterrupt == 1'b0)
               NextPC = (PCr + 16'd1);
            else
               NextPC = PCr;
         3'b010 :
            NextPC = {D_IN, DR};
         3'b011 :
            NextPC = NewPCWithOffset16;
         3'b100 :
            NextPC = NewPCWithOffset;
         3'b101 :
            NextPC = NewPCWithOffset16;
         3'b110 :
            NextPC = {AAH, AAL};
         3'b111 :
            if (PCDec == 1'b1)
               NextPC = (PCr - 16'd3);
            else
               NextPC = PCr;
         default :
            NextPC = PCr;
      endcase
   end

   always @(posedge CLK) begin
      if (RST_N == 1'b0)
      begin
         PCr <= 16'b0;
         PCOffset <= 16'b0;
      end
      else
      begin
         if (EN == 1'b1)
         begin
            PCOffset <= ({D_IN, DR});
            PCr <= NextPC;
         end
      end
   end

   assign JumpNoOfl = ((~(PCr[8] ^ NewPCWithOffset[8]))) & ((~LOAD_PC[0])) & ((~LOAD_PC[1])) & LOAD_PC[2];

   assign AALCtrl = ADDR_CTRL[7:5];
   assign AAHCtrl = ADDR_CTRL[4:2];
   assign ABSCtrl = ADDR_CTRL[1:0];


   always @*
   begin
      case (IND_CTRL)
         2'b00 :
            if (AALCtrl[2] == 1'b0)
               NewAAL = (({1'b0, AAL}) + ({1'b0, X[7:0]}));
            else
               NewAAL = (({1'b0, DL}) + ({1'b0, X[7:0]}));
         2'b01 :
            if (AALCtrl[2] == 1'b0)
               NewAAL = (({1'b0, AAL}) + ({1'b0, Y[7:0]}));
            else
               NewAAL = (({1'b0, DL}) + ({1'b0, Y[7:0]}));
         2'b10 :
            NewAAL = {1'b0, X[7:0]};
         2'b11 :
            NewAAL = {1'b0, Y[7:0]};
         default :
            ;
      endcase

      if (e6502 == 1'b0)
         case (IND_CTRL)
            2'b00 :
               if (AAHCtrl[2] == 1'b0)
                  NewAAH = (({1'b0, AAH}) + ({1'b0, X[15:8]}));
               else
                  NewAAH = (({1'b0, DH}) + ({1'b0, X[15:8]}) + ({8'b00000000, NewAAL[8]}));
            2'b01 :
               if (AAHCtrl[2] == 1'b0)
                  NewAAH = (({1'b0, AAH}) + ({1'b0, Y[15:8]}));
               else
                  NewAAH = (({1'b0, DH}) + ({1'b0, Y[15:8]}) + ({8'b00000000, NewAAL[8]}));
            2'b10 :
               NewAAH = {1'b0, X[15:8]};
            2'b11 :
               NewAAH = {1'b0, Y[15:8]};
            default :
               ;
         endcase
      else
         if (AAHCtrl[2] == 1'b0)
            NewAAH = {1'b0, AAH};
         else
            NewAAH = {1'b0, DH};
   end

   assign InnerDS = (ABSCtrl == 2'b11 & (AALCtrl[2] == 1'b1 | AAHCtrl[2] == 1'b1)) ? S :
                    (e6502 == 1'b0) ? D :
                    {D[15:8], 8'h00};

   assign NewDL = (({1'b0, InnerDS[7:0]}) + ({1'b0, D_IN}));
   assign NewAAHWithCarry = (NewAAH + ({8'b00000000, SavedCarry}));


   always @(posedge CLK)
      if (RST_N == 1'b0)
      begin
         AAL <= 8'd0;
         AAH <= 8'd0;
         AB <= 8'd0;
         DL <= 8'd0;
         DH <= 8'd0;
         AAHCarry <= 1'b0;
         SavedCarry <= 1'b0;
      end
      else
      begin
         if (EN == 1'b1)
         begin
            case (AALCtrl)
               3'b000 :
                  begin
                     if (IND_CTRL[1] == 1'b1)
                        AAL <= NewAAL[7:0];
                     SavedCarry <= 1'b0;
                  end
               3'b001 :
                  begin
                     AAL <= NewAAL[7:0];
                     SavedCarry <= NewAAL[8];
                  end
               3'b010 :
                  begin
                     AAL <= D_IN;
                     SavedCarry <= 1'b0;
                  end
               3'b011 :
                  begin
                     AAL <= NewPCWithOffset16[7:0];
                     SavedCarry <= 1'b0;
                  end
               3'b100 :
                  begin
                     DL <= NewAAL[7:0];
                     SavedCarry <= NewAAL[8];
                  end
               3'b101 :
                  begin
                     DL <= NewDL[7:0];
                     SavedCarry <= NewDL[8];
                  end
               3'b111 :
                  ;
               default :
                  ;
            endcase

            case (AAHCtrl)
               3'b000 :
                  if (IND_CTRL[1] == 1'b1)
                  begin
                     AAH <= NewAAH[7:0];
                     AAHCarry <= 1'b0;
                  end
               3'b001 :
                  begin
                     AAH <= NewAAHWithCarry[7:0];
                     AAHCarry <= NewAAHWithCarry[8];
                  end
               3'b010 :
                  begin
                     AAH <= D_IN;
                     AAHCarry <= 1'b0;
                  end
               3'b011 :
                  begin
                     AAH <= NewPCWithOffset16[15:8];
                     AAHCarry <= 1'b0;
                  end
               3'b100 :
                  begin
                     DH <= NewAAH[7:0];
                     AAHCarry <= 1'b0;
                  end
               3'b101 :
                  begin
                     DH <= InnerDS[15:8];
                     AAHCarry <= 1'b0;
                  end
               3'b110 :
                  begin
                     DH <= (DH + ({7'b0000000, SavedCarry}));
                     AAHCarry <= 1'b0;
                  end
               3'b111 :
                  ;
               default :
                  ;
            endcase

            case (ABSCtrl)
               2'b00 :
                  ;
               2'b01 :
                  AB <= D_IN;
               2'b10 :
                  AB <= (D_IN + ({7'b0000000, NewAAHWithCarry[8]}));
               2'b11 :
                  if (AALCtrl[2] == 1'b0 & AAHCtrl[2] == 1'b0)
                     AB <= DBR;
               default :
                  ;
            endcase
         end
      end

   assign AALCarry = NewAAL[8];
   assign AA = {AAHCarry, AAH, AAL};
   assign DX = {DH, DL};
   assign PC = PCr;

endmodule


// ---- upstream: src/65C816/ALU.v ----
import P65816::*;

module ALU(
   input [15:0]  L,
   input [15:0]  R,
   input ALUCtrl_r CTRL,
   input         w16,
   input         BCD,
   input         CI,
   input         VI,
   input         SI,
   output  reg   CO,
   output  reg   VO,
   output  reg   SO,
   output        ZO,
   output [15:0] RES,
   output [15:0] IntR
);

   reg [15:0]    IntR16;
   reg [7:0]     IntR8;
   reg           CR8;
   reg           CR16;
   wire          CR;
   reg           ZR;
   wire          CIIn;
   wire          ADDIn;
   wire          BCDIn;

   wire [15:0]   AddR;
   wire          AddCO;
   wire          AddVO;
   reg [15:0]    Result16;
   reg [7:0]     Result8;


   always @*
   begin
      CR8 = CI;
      CR16 = CI;
      case (CTRL.fstOp)
         3'b000 :
            begin
               CR8 = R[7];
               CR16 = R[15];
               IntR8 = {R[6:0], 1'b0};
               IntR16 = {R[14:0], 1'b0};
            end
         3'b001 :
            begin
               CR8 = R[7];
               CR16 = R[15];
               IntR8 = {R[6:0], CI};
               IntR16 = {R[14:0], CI};
            end
         3'b010 :
            begin
               CR8 = R[0];
               CR16 = R[0];
               IntR8 = {1'b0, R[7:1]};
               IntR16 = {1'b0, R[15:1]};
            end
         3'b011 :
            begin
               CR8 = R[0];
               CR16 = R[0];
               IntR8 = {CI, R[7:1]};
               IntR16 = {CI, R[15:1]};
            end
         3'b100 :
            begin
               IntR8 = R[7:0];
               IntR16 = R;
            end
         3'b101 :
            begin
               IntR8 = R[15:8];
               IntR16 = {R[7:0], R[15:8]};
            end
         3'b110 :
            begin
               IntR8 = ((R[7:0]) - 8'd1);
               IntR16 = (R - 16'd1);
            end
         3'b111 :
            begin
               IntR8 = ((R[7:0]) + 8'd1);
               IntR16 = (R + 16'd1);
            end
         default :
            ;
      endcase
   end

   assign CR = (w16 == 1'b0) ? CR8 :
               CR16;

   assign CIIn = CR | ~CTRL.secOp[0];
   assign ADDIn = ~CTRL.secOp[2];
   assign BCDIn = BCD & CTRL.secOp[0];


   AddSubBCD AddSub(.A(L), .B(R), .CI(CIIn), .ADD(ADDIn), .BCD(BCDIn), .w16(w16), .S(AddR), .CO(AddCO), .VO(AddVO));


   always @*
   begin: xhdl0
      reg [7:0]     temp8;
      reg [15:0]    temp16;
      ZR = 1'b0;
      temp8 = 8'b0;
      temp16 = 16'b0;
      case (CTRL.secOp)
         3'b000 :
            begin
               CO = CR;
               Result8 = L[7:0] | IntR8;
               Result16 = L | IntR16;
            end
         3'b001 :
            begin
               CO = CR;
               Result8 = L[7:0] & IntR8;
               Result16 = L & IntR16;
            end
         3'b010 :
            begin
               CO = CR;
               Result8 = L[7:0] ^ IntR8;
               Result16 = L ^ IntR16;
            end
         3'b011, 3'b110, 3'b111 :
            begin
               CO = AddCO;
               Result8 = AddR[7:0];
               Result16 = AddR;
            end
         3'b100 :
            begin
               CO = CR;
               Result8 = IntR8;
               Result16 = IntR16;
            end
         3'b101 :
            begin
               CO = CR;
               if (CTRL.fc == 1'b0)
               begin
                  Result8 = IntR8 & ((~L[7:0]));
                  Result16 = IntR16 & ((~L));
               end
               else
               begin
                  Result8 = IntR8 | L[7:0];
                  Result16 = IntR16 | L;
               end

               temp8 = IntR8 & L[7:0];
               temp16 = IntR16 & L;
               if ((temp8 == 8'h00 & w16 == 1'b0) | (temp16 == 16'h0000 & w16 == 1'b1))
                  ZR = 1'b1;
            end
         default :
            ;
      endcase
   end


   always @*
   begin
      VO = VI;
      if (w16 == 1'b0)
         SO = Result8[7];
      else
         SO = Result16[15];
      case (CTRL.secOp)
         3'b001 :
            if (CTRL.fc == 1'b1)
            begin
               if (w16 == 1'b0)
               begin
                  VO = IntR8[6];
                  SO = IntR8[7];
               end
               else
               begin
                  VO = IntR16[14];
                  SO = IntR16[15];
               end
            end
         3'b011 :
            VO = AddVO;
         3'b101 :
            SO = SI;
         3'b111 :
            if (CTRL.fc == 1'b1)
               VO = AddVO;
         default :
            ;
      endcase
   end

   assign ZO = (CTRL.secOp == 3'b101) ? ZR :
               ((w16 == 1'b0 & Result8 == 8'h00) | (w16 == 1'b1 & Result16 == 16'h0000)) ? 1'b1 :
               1'b0;

   assign RES = (w16 == 1'b0) ? {8'h00, Result8} :
                Result16;
   assign IntR = (w16 == 1'b0) ? {8'h00, IntR8} :
                 IntR16;

endmodule


// ---- upstream: src/65C816/AddSubBCD.v ----

module AddSubBCD(A, B, CI, ADD, BCD, w16, S, CO, VO);
   input [15:0]  A;
   input [15:0]  B;
   input         CI;
   input         ADD;
   input         BCD;
   input         w16;
   output [15:0] S;
   output        CO;
   output        VO;

   wire          VO1;
   wire          VO3;
   wire          CO0;
   wire          CO1;
   wire          CO2;
   wire          CO3;

   BCDAdder add0(.A(A[3:0]), .B(B[3:0]), .CI(CI), .S(S[3:0]), .CO(CO0), .VO(), .ADD(ADD), .BCD(BCD));
   BCDAdder add1(.A(A[7:4]), .B(B[7:4]), .CI(CO0), .S(S[7:4]), .CO(CO1), .VO(VO1), .ADD(ADD), .BCD(BCD));
   BCDAdder add2(.A(A[11:8]), .B(B[11:8]), .CI(CO1), .S(S[11:8]), .CO(CO2), .VO(), .ADD(ADD), .BCD(BCD));
   BCDAdder add3(.A(A[15:12]), .B(B[15:12]), .CI(CO2), .S(S[15:12]), .CO(CO3), .VO(VO3), .ADD(ADD), .BCD(BCD));

   assign VO = (w16 == 1'b0) ? VO1 :
               VO3;
   assign CO = (w16 == 1'b0) ? CO1 :
               CO3;

endmodule


// ---- upstream: src/65C816/BCDAdder.v ----

module BCDAdder(A, B, CI, S, CO, VO, ADD, BCD);
   input [3:0]  A;
   input [3:0]  B;
   input        CI;

   output [3:0] S;
   output       CO;
   output       VO;

   input        ADD;
   input        BCD;


   wire [3:0]   B2;
   wire [3:0]   BIN_S;
   wire         BIN_CO;
   wire [3:0]   BCD_B;
   wire         BCD_CO;

   assign B2 = B ^ {4{~ADD}};


   adder4 bin_adder(.A(A), .B(B2), .CI(CI), .S(BIN_S), .CO(BIN_CO));

   assign BCD_CO = (((BIN_S[3] & BIN_S[2]) | (BIN_S[3] & BIN_S[1])) & ADD) | ((~(BIN_CO ^ ADD)));
   assign BCD_B = {(~ADD), ((BCD_CO & BCD) ^ (~ADD)), ((BCD_CO & BCD) ^ (~ADD)), (~ADD)};

   adder4 bcd_corr_adder(.A(BIN_S), .B(BCD_B), .CI((~ADD)), .S(S), .CO());

   assign CO = (BCD == 1'b0) ? BIN_CO :
               BCD_CO ^ (~ADD);
   assign VO = ((~(A[3] ^ B2[3]))) & (A[3] ^ BIN_S[3]);

endmodule


// ---- upstream: src/65C816/adder4.v ----

module adder4(A, B, CI, S, CO);
   input [3:0]  A;
   input [3:0]  B;
   input        CI;
   output [3:0] S;
   output       CO;


   wire         CO0;
   wire         CO1;
   wire         CO2;


   bit_adder b_add0(A[0], B[0], CI, S[0], CO0);

   bit_adder b_add1(A[1], B[1], CO0, S[1], CO1);

   bit_adder b_add2(A[2], B[2], CO1, S[2], CO2);

   bit_adder b_add3(A[3], B[3], CO2, S[3], CO);

endmodule


// ---- upstream: src/65C816/bit_adder.v ----

module bit_adder(A, B, CI, S, CO);
   input   A;
   input   B;
   input   CI;
   output  S;
   output  CO;
   assign S = ((~A) & (~B) & CI) | ((~A) & B & (~CI)) | (A & (~B) & (~CI)) | (A & B & CI);
   assign CO = ((~A) & B & CI) | (A & (~B) & CI) | (A & B & (~CI)) | (A & B & CI);

endmodule


