always @(posedge CLK) begin
    if(RST_N == 1'b0) begin
      PSW <= 8'b0;
      SP <= 8'b0;
      T <= 8'b0;
    end else begin
      if (EN == 1'b0) begin
        if (DBG_DAT_WR == 1'b1) begin
          case(DBG_REG)
          8'h05 : begin
            PSW <= DBG_DAT_IN;
;
          end
          8'h06 : begin
            SP <= DBG_DAT_IN;
;
          end
          default : begin
          end
          endcase
        end
      end else begin
        case(MC.LOAD_SP)
          2'b00 : ;
          2'b01 : SP <= (SP) + 1;
          2'b10 : SP <= (SP) - 1;
          2'b11 : SP <= X;
          default : ;
        endcase

        case(MC.LOAD_T)
          2'b01 : T <= D_IN;
          2'b10 : T <= AluR;
          default : ;
        endcase

        case(MC.LOAD_P)
          3'b000 : PSW <= PSW;          // No Op
          3'b001 : begin                // ALU
            PSW[1:0] <= {ZO,CO};
            PSW[3] <= HO;
            PSW[7:6] <= {SO,VO};
          end
          3'b010: begin                 // BRK
            PSW[2] <= 0;
            PSW[4] <= ~IsResetInterrupt;
          end
          3'b011 : PSW <= D_IN;         // RETI/POP PSW
          3'b100 : begin
            case(IR[7:5])
              3'b001 : PSW[5] <= 1'b0;  // CLRP 20
              3'b010 : PSW[5] <= 1'b1;  // SETP 40
              3'b011 : PSW[0] <= 1'b0;  // CLRC 60
              3'b100 : PSW[0] <= 1'b1;  // SETC 80
              3'b101 : PSW[2] <= 1'b1;  // EI A0
              3'b110 : PSW[2] <= 1'b0;  // DI C0
              3'b111 : begin            // CLRV E0
                PSW[6] <= 1'b0;
                PSW[3] <= 1'b0;
              end
              default : begin end
            endcase
          end
          3'b101 : PSW[0] <= AluR[0];
          default : PSW <= PSW;
        endcase
      end
    end
end

assign D_OUT =  MC.OUT_BUS == 3'b001 ? SB :
                MC.OUT_BUS == 3'b010 ? AluR :
                MC.OUT_BUS == 3'b011 ? PSW :
                MC.OUT_BUS == 3'b100 ? PC[7:0] :
                MC.OUT_BUS == 3'b101 ? PC[15:8] :
                8'hFF;

always @* begin
    WE_N = 1'b1;
    if (MC.OUT_BUS != 3'b000 && ~IsResetInterrupt/* && EN*/)
      WE_N = 1'b0;
end

always @* begin
    case(MC.ADDR_BUS)
    2'b00 :
      A_OUT = PC;

    2'b01 : begin
      if (IR == 8'h0A || IR == 8'h2A || IR == 8'h4A || IR == 8'h6A || IR == 8'h8A || IR == 8'hAA || IR == 8'hCA || IR == 8'hEA)
        A_OUT = AX & 16'h1FFF;
      else
        A_OUT = AX;
    end

    2'b10 :
      A_OUT = {8'h01,SP};

    2'b11 : begin
      if (IR[3:0] == 4'h1)
        A_OUT = {8'hFF,3'b110, ~IR[7:4],STATE[0]};        //FFC0-FFDF
      else begin
        if (GotInterrupt == 1'b1)
          A_OUT = {8'hFF, 2'b11, ~IsIRQInterrupt, 4'b1111, STATE[0]}; //FFFE/F
        else
          A_OUT = {8'hFF, 3'b110, ~IR[7:4], STATE[0]};
      end
    end
    default : ;
    endcase
end

assign IrqActive =  ~IRQ_N &  ~PSW[2];
always @(posedge CLK) begin
    if(RST_N == 1'b0) begin
      GotInterrupt <= 1'b1;
      IsResetInterrupt <= 1'b1;
      IsIRQInterrupt <= 1'b0;
      STPExec <= 1'b0;
    end else begin
      if(EN == 1'b0) begin
        if(DBG_DAT_WR == 1'b1 && (DBG_REG == 8'h03 || DBG_REG == 8'h04)) begin
          GotInterrupt <= 1'b0;
          //need for SPC Player
          IsResetInterrupt <= 1'b0;
        end
      end
      else begin
        if (LAST_CYCLE) begin
          GotInterrupt <= IrqActive;
          IsResetInterrupt <= 1'b0;

          if (IrqActive == 1'b1 && IsIRQInterrupt == 1'b0)
            IsIRQInterrupt <= 1'b1;
          else
            IsIRQInterrupt <= 1'b0;
        end

        if (STATE == 4'b0000 && ~IsResetInterrupt) begin   // nand2mario: when resetting, ignore SLEEP/STP
          if (D_IN == 8'hEF || D_IN == 8'hFF) begin
            // SLEEP, STP
            STPExec <= 1'b1;
          end
        end
      end
    end
end

//debug
always @* begin
    case(DBG_REG)
    8'h00 : begin
      DBG_DAT_OUT = A;
    end
    8'h01 : begin
      DBG_DAT_OUT = X;
    end
    8'h02 : begin
      DBG_DAT_OUT = Y;
    end
    8'h03 : begin
      DBG_DAT_OUT = PC[7:0];
    end
    8'h04 : begin
      DBG_DAT_OUT = PC[15:8];
    end
    8'h05 : begin
      DBG_DAT_OUT = PSW;
    end
    8'h06 : begin
      DBG_DAT_OUT = SP;
    end
    8'h07 : begin
      DBG_DAT_OUT = AX[7:0];
    end
    8'h08 : begin
      DBG_DAT_OUT = AX[15:8];
    end
    default : begin
      DBG_DAT_OUT = 8'h00;
    end
    endcase
end

`ifdef VERILATOR

