MCODE0[2046]={2'bXX,2'bXX,6'bXXXXXX,5'bXXXXX,2'bXX,5'bXXXXX,6'bXXXXXX,3'bXXX};
MCODE0[2047]={2'bXX,2'bXX,6'bXXXXXX,5'bXXXXX,2'bXX,5'bXXXXX,6'bXXXXXX,3'bXXX};
end


SpcMicroInst_r MI;
SpcALUCtrl_r ALUFlags;
SpcRegCtrl_r R;

always @(posedge CLK) begin
    if (~RST_N)
        MI <= MCODE0[0]; // {2'b0, 2'b0, 6'b0, 5'b1, 2'b0, 5'b0, 6'b0, 3'b0};
    else if (EN) begin
		MI <= MCODE0[{IR, STATE[2:0]}];
		if (IR == 8'h9E && STATE[3])		// DIV
			MI <= MCODE0[{9'h1,STATE[1:0]}];
		else if (IR == 8'hCF && STATE[3])	// MUL
			MI <= MCODE0[3];
	end
end

always @* begin
	case (MI.ALUCtrl)
	//             fstOp   secOp chgVO chgHO intC chgCO
	0: ALUFlags =  {3'b110,4'b0011,1'b0,1'b0,1'b0,1'b0};// 000000 LOAD
	1: ALUFlags =  {3'b100,4'b1011,1'b0,1'b0,1'b1,1'b0};// 000001 DECW
	2: ALUFlags =  {3'b101,4'b1011,1'b0,1'b0,1'b0,1'b0};// 000010 DEC
	3: ALUFlags =  {3'b101,4'b1001,1'b0,1'b0,1'b0,1'b0};// 000011 INC
	4: ALUFlags =  {3'b110,4'b0000,1'b0,1'b0,1'b0,1'b0};// 000100 OR
	5: ALUFlags =  {3'b110,4'b0001,1'b0,1'b0,1'b0,1'b0};// 000101 AND
	6: ALUFlags =  {3'b110,4'b0010,1'b0,1'b0,1'b0,1'b0};// 000110 EOR
	7: ALUFlags =  {3'b110,4'b1000,1'b1,1'b1,1'b0,1'b1};// 000111 ADC
	8: ALUFlags =  {3'b110,4'b1010,1'b1,1'b1,1'b0,1'b1};// 001000 SBC
	9: ALUFlags =  {3'b100,4'b1001,1'b0,1'b0,1'b1,1'b0};// 001001 INCW
	10: ALUFlags = {3'b000,4'b0011,1'b0,1'b0,1'b0,1'b1};// 001010 ASL
	11: ALUFlags = {3'b010,4'b0011,1'b0,1'b0,1'b0,1'b1};// 001011 LSR
	12: ALUFlags = {3'b001,4'b0011,1'b0,1'b0,1'b0,1'b1};// 001100 ROL
	13: ALUFlags = {3'b011,4'b0011,1'b0,1'b0,1'b0,1'b1};// 001101 ROR
	14: ALUFlags = {3'b110,4'b0100,1'b0,1'b0,1'b0,1'b0};// 001110 TCLR1
	15: ALUFlags = {3'b110,4'b0101,1'b0,1'b0,1'b0,1'b0};// 001111 TSET1
	16: ALUFlags = {3'b110,4'b1011,1'b0,1'b0,1'b1,1'b1};// 010000 CMPW
	17: ALUFlags = {3'b110,4'b1001,1'b0,1'b0,1'b0,1'b1};// 010001 ADD
	18: ALUFlags = {3'b110,4'b1001,1'b1,1'b1,1'b1,1'b1};// 010010 ADDW
	19: ALUFlags = {3'b110,4'b1011,1'b0,1'b0,1'b0,1'b1};// 010011 SUB/CMP
	20: ALUFlags = {3'b110,4'b1011,1'b1,1'b1,1'b1,1'b1};// 010100 SUBW
	21: ALUFlags = {3'b111,4'b0001,1'b0,1'b0,1'b0,1'b0};// 010101 CLR1
	22: ALUFlags = {3'b110,4'b0000,1'b0,1'b0,1'b0,1'b0};// 010110 SET1
	23: ALUFlags = {3'b110,4'b0001,1'b0,1'b0,1'b0,1'b0};// 010111 AND1
	24: ALUFlags = {3'b111,4'b0001,1'b0,1'b0,1'b0,1'b0};// 011000 NOT AND1
	25: ALUFlags = {3'b110,4'b0000,1'b0,1'b0,1'b0,1'b0};// 011001 OR1
	26: ALUFlags = {3'b111,4'b0000,1'b0,1'b0,1'b0,1'b0};// 011010 NOT OR1
	27: ALUFlags = {3'b110,4'b0010,1'b0,1'b0,1'b0,1'b0};// 011011 EOR1
	28: ALUFlags = {3'b101,4'b0010,1'b0,1'b0,1'b0,1'b0};// 011100 NOTC {C ^ 1}
	29: ALUFlags = {3'b110,4'b0110,1'b0,1'b0,1'b0,1'b0};// 011101 XCN
	30: ALUFlags = {3'b110,4'b1100,1'b0,1'b0,1'b0,1'b1};// 011110 DAA
	31: ALUFlags = {3'b110,4'b1101,1'b0,1'b0,1'b0,1'b1};// 011111 DAS
	32: ALUFlags = {3'b110,4'b1110,1'b0,1'b0,1'b0,1'b0};// 100000 MUL
	33: ALUFlags = {3'b110,4'b1111,1'b1,1'b1,1'b0,1'b0};// 100001 DIV
	default: ALUFlags = 11'b0;
	endcase
end

always @* begin
	case (MI.regMode)
	//      loadPC loadSP loadP loadT
	0: R = {3'b000,2'b00,3'b000,2'b00};//00000
	1: R = {3'b001,2'b00,3'b000,2'b00};//00001 PC++
	2: R = {3'b001,2'b00,3'b001,2'b00};//00010 PC++, Flags
	3: R = {3'b000,2'b00,3'b001,2'b00};//00011 Flags
	4: R = {3'b000,2'b11,3'b000,2'b00};//00100 X->SP
	5: R = {3'b001,2'b00,3'b000,2'b01};//00101 [PC]->T, PC++
	6: R = {3'b000,2'b00,3'b000,2'b01};//00110 []->T
	7: R = {3'b000,2'b00,3'b001,2'b10};//00111 ALU{}->T, Flags
	8: R = {3'b000,2'b00,3'b100,2'b00};//01000 CLR/SET
	9: R = {3'b011,2'b00,3'b000,2'b00};//01001 PC+DR->PC
	10: R = {3'b000,2'b00,3'b101,2'b00};//01010 C change
	11: R = {3'b000,2'b00,3'b000,2'b10};//01011 ALU{}->T
	12: R = {3'b010,2'b00,3'b000,2'b00};//01100 []:DR->PC
	13: R = {3'b000,2'b10,3'b000,2'b00};//01101 Reg->[SP], SP--
	14: R = {3'b100,2'b00,3'b000,2'b00};//01110 AX->PC
	15: R = {3'b000,2'b00,3'b010,2'b00};//01111 1->B
	16: R = {3'b000,2'b01,3'b000,2'b00};//10000 SP++
	17: R = {3'b000,2'b00,3'b011,2'b00};//10001 []->PSW
	18: R = {3'b101,2'b00,3'b000,2'b00};//10010 FF:AL->PC
	default: R = 10'b0;
	endcase
end

assign M = {ALUFlags,
            MI.stateCtrl,
            MI.addrBus,
            MI.addrCtrl,
            R.loadPC,
            R.loadSP,
            MI.regAXY,
            R.loadP,
            R.loadT,
            MI.busCtrl,
            MI.outBus};

endmodule

// ---- upstream: src/spc700/addrgen.v ----
// import spc700::*;

module SPC700_AddrGen(
    input wire CLK,
    input wire RST_N,
    input wire EN,
    input wire [5:0] ADDR_CTRL,
    input wire [2:0] LOAD_PC,
    input wire GotInterrupt,
    input wire [7:0] D_IN,
    input wire [7:0] X,
    input wire [7:0] Y,
    input wire [7:0] S,
    input wire [7:0] T,
    input wire P,
    output wire [15:0] PC,
    output wire [15:0] AX,
    output wire ALCarry,
    input wire [7:0] DBG_REG,
    input wire [7:0] DBG_DAT_IN,
    input wire DBG_DAT_WR,
    output wire [15:0] DBG_NEXT_PC
);

reg [7:0] AL; reg [7:0] AH;
reg SavedCarry;
reg [8:0] NewAL; wire [8:0] NewAH;
wire [7:0] NewAHWithCarry;
wire [15:0] NextAX;
reg [7:0] DR;
reg [15:0] PCr;
reg [15:0] NextPC; wire [15:0] NewPCWithOffset;
wire [1:0] ALCtrl;
wire [1:0] AHCtrl;
wire [1:0] MuxCtrl;

assign ALCtrl = ADDR_CTRL[5:4];
assign AHCtrl = ADDR_CTRL[3:2];
assign MuxCtrl = ADDR_CTRL[1:0];
assign NewPCWithOffset = PCr + {{8{DR[7]}}, DR};
// NewPCWithOffset <= std_logic_vector(unsigned(PCr) + unsigned((7 downto 0 => DR(7)) & DR));
always @* begin
    case(LOAD_PC)
    3'b000 : begin
      NextPC = PCr;
    end
    3'b001 : begin
      if(GotInterrupt == 1'b0) begin
        NextPC = (PCr) + 1;
      end
      else begin
        NextPC = PCr;
      end
    end
    3'b010 : begin
      NextPC = {D_IN,DR};
    end
    3'b011 : begin
      NextPC = NewPCWithOffset;
    end
    3'b100 : begin
      NextPC = {AH,AL};
    end
    3'b101 : begin
      NextPC = {8'hFF,AL};
    end
    default : begin
      NextPC = PCr;
    end
    endcase
end

always @(posedge CLK) begin
    if(RST_N == 1'b0) begin
      PCr <= {16{1'b0}};
      DR <= {8{1'b0}};
    end else begin
      if(EN == 1'b0) begin
        if(DBG_DAT_WR == 1'b1) begin
          case(DBG_REG)
          8'h03 : begin
            PCr[7:0] <= DBG_DAT_IN;
          end
          8'h04 : begin
            PCr[15:8] <= DBG_DAT_IN;
          end
          default : begin
          end
          endcase
        end
      end else begin
        DR <= D_IN;
        PCr <= NextPC;
      end
    end
end

assign DBG_NEXT_PC = NextPC;
always @* begin
    case(MuxCtrl)
    2'b00 : begin
      NewAL = ({1'b0,AL}) + ({1'b0,X});
    end
    2'b01 : begin
      NewAL = ({1'b0,AL}) + ({1'b0,Y});
    end
    2'b10 : begin
      NewAL = {1'b0,DR};
    end
    2'b11 : begin
      NewAL = ({1'b0,DR}) + ({1'b0,Y});
    end
    default : ;
    endcase
end

assign NewAHWithCarry = (AH) + ({7'b0000000,SavedCarry});
assign NextAX = ({AH,AL}) + 1;
always @(posedge CLK) begin
    if(RST_N == 1'b0) begin
      AL <= {8{1'b0}};
      AH <= {8{1'b0}};
      SavedCarry <= 1'b0;
    end else begin
      if(EN == 1'b1) begin
        case(ALCtrl)
        2'b00 : begin
          SavedCarry <= 1'b0;
        end
        2'b01 : begin
          AL <= NewAL[7:0];
          SavedCarry <= NewAL[8];
        end
        2'b10 : begin
          case(MuxCtrl)
          2'b00 : begin
            AL <= D_IN;
          end
          2'b01 : begin
            AL <= X;
          end
          2'b10 : begin
            AL <= Y;
          end
          default : begin
          end
          endcase
          SavedCarry <= 1'b0;
        end
        2'b11 : begin
          AL <= NextAX[7:0];
          SavedCarry <= 1'b0;
        end
        default : begin
        end
        endcase
        case(AHCtrl)
        2'b00 : begin
        end
        2'b01 : begin
          AH <= {7'b0000000,P};
        end
        2'b10 : begin
          AH <= D_IN;
        end
        2'b11 : begin
          if(ALCtrl != 2'b11) begin
            AH <= NewAHWithCarry;
          end
          else begin
            AH <= NextAX[15:8];
          end
        end
        default : begin
        end
        endcase
      end
    end
end

assign ALCarry = NewAL[8];
assign AX = {AH,AL};
assign PC = PCr;

endmodule


// ---- upstream: src/spc700/addsub.v ----
import spc700::*;

module SPC700_AddSub(
    input wire [7:0] A,
    input wire [7:0] B,
    input wire CI,
    input wire ADD,
    output wire [7:0] S,
    output wire CO,
    output wire VO,
    output wire HO
);

wire [7:0] tempB;
reg [7:0] res;
reg C7;

assign tempB = ADD ? B : B ^ 8'hFF;
always @* begin : P1
    reg [4:0] temp0, temp1;

    temp0 = ({1'b0,A[3:0]}) + ({1'b0,tempB[3:0]}) + ({4'b0000,CI});
    temp1 = ({1'b0,A[7:4]}) + ({1'b0,tempB[7:4]}) + ({4'b0000,temp0[4]});
    res = {temp1[3:0],temp0[3:0]};
    C7 = temp1[4];
end

assign S = res;
assign VO = ( ~(A[7] ^ tempB[7])) & (A[7] ^ res[7]);
assign HO = (A[4] ^ B[4] ^ res[4]) ^ ~ADD;
assign CO = C7;

endmodule


// ---- upstream: src/spc700/alu.v ----

import spc700::*;

module SPC700_ALU(
    input wire CLK,
    input wire RST_N,
    input wire EN,
    input SpcALUCtrl_r CTRL,
    input wire [7:0] L,
    input wire [7:0] R,
    input wire w16,
    input wire CI,
    input wire VI,
    input wire SI,
    input wire ZI,
    input wire HI,
    input wire DivZI,
    input wire DivVI,
    input wire DivHI,
    input wire DivSI,
    output wire CO,
    output reg VO,
    output reg SO,
    output wire ZO,
    output wire HO,
    output wire [7:0] RES
);


reg [7:0] tIntR;
reg CR, COut, HOut, VOut, SOut, tZ, SaveC;
wire CIIn, ADDIn;
wire [7:0] AddR, BCDR;
wire AddCO, AddVO, AddHO, BCDCO;
reg [7:0] tResult;

always @* begin
    CR = CI;
    case(CTRL.fstOp)
    3'b000 : begin
      CR = R[7];
      tIntR = {R[6:0],1'b0};
    end
    3'b001 : begin
      CR = R[7];
      tIntR = {R[6:0],CI};
    end
    3'b010 : begin
      CR = R[0];
      tIntR = {1'b0,R[7:1]};
    end
    3'b011 : begin
      CR = R[0];
      tIntR = {CI,R[7:1]};
    end
    3'b100 : begin
      tIntR = 8'h00;
    end
    3'b101 : begin
      //INC,DEC
      tIntR = 8'h01;
    end
    3'b110 : begin
      tIntR = R;
    end
    3'b111 : begin
      tIntR =  ~R;
    end
    default : begin
    end
    endcase
  end

  always @(posedge CLK) begin
    if(RST_N == 1'b0) begin
      SaveC <= 1'b0;
    end else begin
      if(EN == 1'b1) begin
        if(CTRL.secOp[3] == 1'b1) begin
          SaveC <= AddCO;
        end
      end
    end
  end

  assign CIIn = CTRL.intC == 1'b1 ? SaveC : CTRL.secOp[0] == 1'b0 ? CI : CTRL.secOp[1];
  assign ADDIn =  ~CTRL.secOp[1];
  SPC700_AddSub AddSub(
    .A(L),
    .B(tIntR),
    .CI(CIIn),
    .ADD(ADDIn),
    .S(AddR),
    .CO(AddCO),
    .VO(AddVO),
    .HO(AddHO));

  SPC700_BCDAdj BCD(
    .A(L),
    .ADD(CTRL.secOp[0]),
    .CI(CI),
    .HI(HI),
    .R(BCDR),
    .CO(BCDCO));

  always @* begin
    HOut = 1'b0;
    COut = CR;
    case(CTRL.secOp)
    4'b0000 : begin
      tResult = L | tIntR;
    end
    4'b0001 : begin
      tResult = L & tIntR;
    end
    4'b0010 : begin
      tResult = L ^ tIntR;
    end
    4'b0011 : begin
      tResult = tIntR;
    end
    4'b0100 : begin
      //TCLR1
      tResult = tIntR & ( ~L);
    end
    4'b0101 : begin
      //TSET1
      tResult = tIntR | L;
    end
    4'b0110 : begin
      //XCN
      tResult = {tIntR[3:0],tIntR[7:4]};
    end
    4'b1000,4'b1010,4'b1001,4'b1011 : begin
      //ADC,SBC, ADD,SUB
      tResult = AddR;
      COut = AddCO;
      HOut = AddHO;
    end
    4'b1100,4'b1101 : begin
      //DAA,DAS
      tResult = BCDR;
      COut = BCDCO;
    end
    4'b1110 : begin
      //MUL
      tResult = tIntR;
    end
    4'b1111 : begin
      //DIV
      tResult = tIntR;
      HOut = DivHI;
    end
    default : begin
      tResult = 8'h00;
    end
    endcase
  end

  always @* begin
    VOut = VI;
    case(CTRL.secOp)
      4'b1000, 4'b1001: VOut = AddVO;   //ADC,ADD
      4'b1010, 4'b1011: VOut = AddVO;   //SBC,SUB
      4'b1111:          VOut = DivVI;   //DIV
      default : ;
    endcase
  end

  always @* begin
    SOut = SI;
    case (CTRL.secOp)
    4'b1110: SOut = DivSI;          // MUL
    4'b1111: SOut = DivSI;          // DIV
    default: SOut = tResult[7];
    endcase

  end

  assign tZ = CTRL.secOp[3:1] == 3'b111 ? DivZI : tResult == 8'h00 ? 1'b1 : 1'b0;
  assign ZO = w16 ? ZI & tZ : tZ;
  assign CO = CTRL.chgCO ? COut : CI;
  assign VO = CTRL.chgVO ? VOut : VI;
  assign HO = CTRL.chgHO ? HOut : HI;
  assign SO = SOut;
  assign RES = tResult;

endmodule


// ---- upstream: src/spc700/bcdadj.v ----
import spc700::*;

module SPC700_BCDAdj(
    input wire [7:0] A,
    input wire ADD,
    input wire CI,
    input wire HI,
    output wire [7:0] R,
    output wire CO
);

reg [7:0] res;
reg tempC;

always @* begin : P1
    reg [7:0] temp0, temp1;

    temp0 = A;
    tempC = CI;
    temp1 = temp0;
    if(CI == ( ~ADD) || temp0 > 8'h99) begin
        if(ADD == 1'b0) begin
            temp1 = temp0 + 8'h60;
        end else begin
            temp1 = temp0 - 8'h60;
        end
        tempC =  ~ADD;
    end
    res = temp1;
    if(HI == ( ~ADD) || temp1[3:0] > 4'h9) begin
        if(ADD == 1'b0) begin
            res = temp1 + 8'h06;
        end else begin
            res = temp1 - 8'h06;
        end
    end
end

assign R = res;
assign CO = tempC;

endmodule


// ---- upstream: src/spc700/muldiv.v ----

import spc700::*;

module MulDiv(
    input CLK,
    input RST_N,
    input EN,
    input SpcALUCtrl_r CTRL,
    input [7:0] A,
    input [7:0] X,
    input [7:0] Y,
    output [15:0] RES,
    output ZO,
    output VO,
    output HO,
    output SO
);

reg [15:0] tResult;
reg tV, tZ, tS;
reg [15:0] mulRes, mulTemp;
reg [15:0] mulA;
reg [7:0] mulY;
reg [16:0] divt;
reg divOverflow, divV, divH;
reg [7:0] divX;
reg [8:0] quotient;
reg [15:0] remainder;
wire [7:0] divQuotient = divOverflow ? ~quotient[7:0] : quotient[7:0];
wire [7:0] divRemainder = remainder[7:0] + (divOverflow ? divX : 8'd0);

always @(posedge CLK) begin
    if(RST_N == 1'b0) begin
      mulA <= {16{1'b0}};
      mulY <= {8{1'b0}};
      mulRes <= {16{1'b0}};
      divt <= 17'b0;
      divOverflow <= 1'b0;
      divV <= 1'b0;
      divH <= 1'b0;
      divX <= 8'b0;
      remainder <= {16{1'b0}};
      quotient <= {9{1'b0}};
    end else begin
      if(EN == 1'b1) begin
        if(CTRL.secOp == 4'b1110) begin
          mulRes <= mulTemp;
          mulA <= {mulA[14:0],1'b0};
          mulY <= {1'b0,mulY[7:1]};
        end
        else if(CTRL.secOp == 4'b1111) begin
          if(remainder >= divt) begin
            remainder <= remainder - divt;
            quotient <= {quotient[7:0],1'b1};
          end
          else begin
            quotient <= {quotient[7:0],1'b0};
          end
          divt <= {1'b0,divt[16:1]};
        end
        else begin
          mulA <= {8'b00000000,A};
          mulY <= Y;
          mulRes <= {16{1'b0}};
          divOverflow <= {1'b0,Y} >= {X,1'b0};
          divV <= Y >= X;
          divH <= Y[3:0] >= X[3:0];
          divX <= X;
          if ({1'b0,Y} >= {X,1'b0}) begin
            divt <= (17'd256 - {9'b0,X}) << 8;
            remainder <= {Y,A} - {X,9'b0};
          end else begin
            divt <= {1'b0,X,8'b0};
            remainder <= {Y,A};
          end
          quotient <= {9{1'b0}};
        end
      end
    end
end

always @* begin
    mulTemp = {16{1'b0}};
    if(CTRL.secOp == 4'b1110) begin
      if(mulY[0] == 1'b1) begin
        mulTemp = mulRes + mulA;
      end
      else begin
        mulTemp = mulRes;
      end
      tResult = mulTemp;
      if(mulTemp[15:8] == 0) begin
        tZ = 1'b1;
      end
      else begin
        tZ = 1'b0;
      end
      tV = 1'b0;
      tS = mulTemp[15];
    end
    else if(CTRL.secOp == 4'b1111) begin
      tResult = {divRemainder,divQuotient};
      if(divQuotient == 0) begin
        tZ = 1'b1;
      end
      else begin
        tZ = 1'b0;
      end
      tV = divV;
      tS = divQuotient[7];
    end
    else begin
      tResult = {16{1'b0}};
      tZ = 1'b0;
      tV = 1'b0;
      tS = 1'b0;
    end
end

assign RES = tResult;
assign ZO = tZ;
assign VO = tV;
assign SO = tS;
assign HO = divH;

endmodule

`undef VERILATOR
